#!/usr/bin/env node
// sync-check.mjs [--repair] [--json]
//
// Self-healing check for linked and replicated agent accounts. It reads the manifest that
// `accounts.mjs apply` wrote, verifies every managed link, generated file and managed MCP server
// definition, and with --repair restores what is safe to restore.
//
// SELF-CONTAINED ON PURPOSE: no imports from the skill, zero npm dependencies. `accounts.mjs
// install-check` copies this one file to <home>/.novarc-powers/novarc-harness-doctor/sync/ so the
// check keeps working when the skill itself is fetched on demand. The rest of the accounts
// feature imports its primitives from here, so each of them has exactly one implementation.
//
// Contract when it runs from a session-start hook: print nothing when everything is fine, one
// short line when something was repaired or has drifted, and ALWAYS exit 0. It never reads
// credentials, sessions or history, never prints file contents or absolute home paths, never
// overwrites a file somebody edited by hand, never writes through a link or into a file that
// gained another name, and never writes INTO a file at all: new bytes go to a temp file that is
// renamed over the old one, so a write that fails, or a process that dies in the middle of one,
// leaves every name holding its complete old bytes or its complete new bytes. What a run that
// died left unfinished is finished, or cleaned up, by the next run (see recoverWrites).
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

export const IS_WIN = process.platform === 'win32';
export const TOOL = 'novarc-harness-doctor';
export const MANIFEST_VERSION = 1;
export const BLOCK_START = `# ${TOOL}:start`;
export const BLOCK_END = `# ${TOOL}:end`;
export const GENERATED_PREFIX = `<!-- generated by ${TOOL} from `;
export const MCP_PREFIX = 'mcp servers/';
export const SKILL_PREFIX = 'skills/';

// ---------------------------------------------------------------------------------------------
// Home and paths. Everything that needs the home directory goes through homeDir().
// ---------------------------------------------------------------------------------------------

/** The home directory; NOVARC_POWERS_HOME overrides it (tests and dry runs use a fake home). */
export function homeDir() {
  const o = process.env.NOVARC_POWERS_HOME;
  return path.resolve(o && o.trim() ? o.trim() : os.homedir());
}

export function syncDir(home = homeDir()) {
  return path.join(home, '.novarc-powers', TOOL, 'sync');
}

export function manifestFile(home = homeDir()) {
  return path.join(syncDir(home), 'manifest.json');
}

export function stableCheckPath(home = homeDir()) {
  return path.join(syncDir(home), 'sync-check.mjs');
}

export function pathKey(p) {
  const n = path.resolve(String(p));
  return IS_WIN ? n.toLowerCase() : n;
}

export function isInside(child, parent) {
  const c = pathKey(child);
  const p = pathKey(parent);
  if (c === p) return true;
  return c.startsWith(p.endsWith(path.sep) ? p : p + path.sep);
}

/** Display form: home as `~`, forward slashes. Never an absolute path under home. */
export function displayPath(p, home = homeDir()) {
  if (p === undefined || p === null) return p;
  const abs = path.resolve(String(p));
  if (isInside(abs, home)) {
    const rel = path.relative(home, abs).replace(/\\/g, '/');
    return rel ? `~/${rel}` : '~';
  }
  return abs.replace(/\\/g, '/');
}

/** Replace the home directory (native, forward-slash and /c/ forms) with `~` inside free text. */
export function scrub(text, home = homeDir()) {
  if (typeof text !== 'string') return text;
  const variants = new Set();
  for (const h of [home, realpathSafe(home)]) {
    if (!h) continue;
    variants.add(h);
    variants.add(h.replace(/\\/g, '/'));
    variants.add(h.replace(/\\/g, '\\\\'));
    const m = /^([a-zA-Z]):[\\/](.*)$/.exec(h);
    if (m) variants.add(`/${m[1].toLowerCase()}/${m[2].replace(/\\/g, '/')}`);
  }
  let s = text;
  const esc = (x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  for (const v of [...variants].sort((a, b) => b.length - a.length)) s = s.replace(new RegExp(esc(v), IS_WIN ? 'gi' : 'g'), '~');
  return s;
}

// ---------------------------------------------------------------------------------------------
// File helpers
// ---------------------------------------------------------------------------------------------

export function lstatSafe(p) { try { return fs.lstatSync(p); } catch { return null; } }
export function statSafe(p) { try { return fs.statSync(p); } catch { return null; } }
export function realpathSafe(p) { try { return fs.realpathSync.native(p); } catch { return null; } }
export function readlinkSafe(p) { try { return fs.readlinkSync(p); } catch { return null; } }
export function isFile(p) { const s = statSafe(p); return !!(s && s.isFile()); }
export function isDir(p) { const s = statSafe(p); return !!(s && s.isDirectory()); }
export function readdirSafe(p) { try { return fs.readdirSync(p, { withFileTypes: true }); } catch { return []; } }

export function readBuf(p, maxBytes = 32 * 1024 * 1024) {
  try {
    const st = fs.statSync(p);
    if (!st.isFile() || st.size > maxBytes) return null;
    return fs.readFileSync(p);
  } catch { return null; }
}

export function readText(p, maxBytes = 8 * 1024 * 1024) {
  const b = readBuf(p, maxBytes);
  return b === null ? null : b.toString('utf8');
}

export function sha256(data) {
  return crypto.createHash('sha256').update(data).digest('hex');
}

export function hashFile(p) {
  const b = readBuf(p, 64 * 1024 * 1024);
  return b === null ? null : sha256(b);
}

/** Drop a leading UTF-8 byte order mark. */
export function stripBom(text) {
  return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
}

/** Parse JSON without surfacing the parser's message (it can embed a slice of the input). */
export function parseJson(text) {
  if (typeof text !== 'string') return { ok: false };
  try { return { ok: true, value: JSON.parse(stripBom(text)) }; } catch { return { ok: false }; }
}

/** Stable JSON: object keys sorted at every level. */
export function canon(v) {
  if (Array.isArray(v)) return `[${v.map(canon).join(',')}]`;
  if (v && typeof v === 'object') return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canon(v[k])}`).join(',')}}`;
  return JSON.stringify(v === undefined ? null : v);
}

/** True when both paths are the same file on disk (hardlink peers, or one path reached twice). */
export function sameFile(a, b) {
  try {
    const x = fs.statSync(a, { bigint: true });
    const y = fs.statSync(b, { bigint: true });
    return x.dev === y.dev && x.ino === y.ino && x.ino !== 0n;
  } catch { return false; }
}

export function mkdirp(dir) { fs.mkdirSync(dir, { recursive: true }); }

// ---- Writing without ever leaving a torn file ----------------------------------------------
//
// No file is ever written in place. The new bytes go to a temp file beside the destination
// (written, synced, read back) and the temp is renamed over it: one atomic step. A file that has
// other names (hardlinks) gets each KNOWN other name switched over the same way, one rename per
// name. Before the first byte, a record of the whole operation is written durably under the sync
// state folder; a run that finds such a record finishes or clears what a dead run left.

/** Where the record of a write in progress is kept until that write is done. */
export function recoveryDir(home = homeDir()) {
  return path.join(syncDir(home), 'recovery');
}

const INTENT_VERSION = 1;
const TEMP_RE = /\.nhd-\d+-[0-9a-f]{8}\.tmp$/;
const LEFTOVER_AGE_MS = 60 * 1000;

/** A temp name beside `file`: the same folder, so that renaming it over `file` is atomic. */
function tempName(file) {
  return `${file}.nhd-${process.pid}-${crypto.randomBytes(4).toString('hex')}.tmp`;
}

/**
 * TESTS ONLY. NOVARC_POWERS_TEST_FAULT lists, separated by commas, the points at which a write
 * is made to fail, so that a failure or a death in the middle of one can be tested without a full
 * disk or a power cut. `point` fails there as a full disk would; `EBUSY@point` (or any other
 * error code) fails there with that code, which is how a rename that is refused for a moment is
 * produced; `kill@point` ends the process on the spot, with nothing unwound; `#n` restricts any
 * of them to the n-th time the point is reached. Every rename has a point of its own, reached
 * right before each attempt (rename-file, rename-name, rename-recovery, rename-temp,
 * rename-link), and `<that>-retry`, reached before each further attempt.
 * The points, in the order a write passes them: record (half of the record written), intent (the
 * record is durable), temp (half of the new bytes written), staged (the temp is complete),
 * peer-staged (a link for another name is ready), committed (the rename over the destination is
 * done), peer (before another name is switched over), finished (before the record is removed);
 * and, outside a write, copied (a plain copy sits in its temp), linked (a link that replaces a
 * file sits under its temp name) and journal (half of a journal that is saved durably). The
 * steps of `accounts.mjs apply` and `undo` add their own through testFault.
 * NOVARC_POWERS_TEST_EDIT=`point[#n]=file` does, at that point, what another program might in
 * the middle of a write: it writes `file` (see otherProgram). Unset, as both always are outside
 * the tests, this costs two environment lookups.
 */
const faultHits = new Map();
let faultSpec = null;
function fault(point, first) {
  const edit = process.env.NOVARC_POWERS_TEST_EDIT;
  if (edit) otherProgram(point, edit);
  const spec = process.env.NOVARC_POWERS_TEST_FAULT;
  if (!spec) return;
  if (spec !== faultSpec) { faultSpec = spec; faultHits.clear(); } // a new list: its counts start again
  for (const entry of spec.split(',')) {
    const m = /^(?:(kill|E[A-Z]+)@)?([a-z-]+)(?:#(\d+))?$/.exec(entry.trim());
    if (!m || m[2] !== point) continue;
    const n = (faultHits.get(entry) || 0) + 1;
    faultHits.set(entry, n);
    if (m[3] && n !== Number(m[3])) continue;
    if (first) first();
    if (m[1] === 'kill') {
      try { process.kill(process.pid, 'SIGKILL'); } catch { /* not possible here: exit instead */ }
      process.exit(99);
    }
    if (m[1]) throw Object.assign(new Error(`${m[1]} (simulated)`), { code: m[1] });
    throw Object.assign(new Error('no space left on device (simulated)'), { code: 'ENOSPC' });
  }
}

/** TESTS ONLY: at the point named in `spec` (`point[#n]=file`), write that file in place. */
function otherProgram(point, spec) {
  const m = /^([a-z-]+)(?:#(\d+))?=(.+)$/.exec(spec);
  if (!m || m[1] !== point) return;
  const n = (faultHits.get(spec) || 0) + 1;
  faultHits.set(spec, n);
  if (n === Number(m[2] || 1)) fs.writeFileSync(m[3], 'EDITED BY ANOTHER PROGRAM\n');
}

/** TESTS ONLY: a fault point of the code built on these primitives (see `fault`). */
export function testFault(point) { fault(point); }

/** Write the whole buffer at the start of an open file. */
function writeAll(fd, buf, point) {
  fault(point, () => { if (buf.length > 1) fs.writeSync(fd, buf, 0, buf.length >> 1, 0); });
  let off = 0;
  while (off < buf.length) {
    const n = fs.writeSync(fd, buf, off, buf.length - off, off);
    if (n <= 0) throw Object.assign(new Error('the write made no progress'), { code: 'EIO' });
    off += n;
  }
}

/** Create the temp file `tmp` holding `buf`: written, synced and read back. Removed on failure. */
function stageFile(tmp, buf, mode, point) {
  let fd;
  try {
    fd = fs.openSync(tmp, 'wx', mode === undefined ? 0o666 : mode);
    writeAll(fd, buf, point);
    if (mode !== undefined && !IS_WIN) fs.fchmodSync(fd, mode); // the mode given to open is cut by the umask
    fs.fsyncSync(fd);
    fs.closeSync(fd);
    fd = undefined;
    if (!fs.readFileSync(tmp).equals(buf)) throw new Error('verification failed: the temp file does not hold what was written');
  } catch (e) {
    if (fd !== undefined) try { fs.closeSync(fd); } catch { /* already closed */ }
    try { fs.unlinkSync(tmp); } catch { /* never created */ }
    throw e;
  }
}

/**
 * Rename `from` over `to`: the one atomic step every write here ends in. A rename can be refused
 * for a moment (a scanner or an indexer holds one of the files, on Windows above all), so it is
 * tried again, briefly: up to three more times, 15, 30 and 45 ms apart.
 *
 * `check` is the last look at what is about to be replaced. It runs immediately before EVERY
 * attempt, the first and each further one: during the wait between two attempts another program
 * can edit the file, or its folder can be moved away, and an attempt made on the strength of a
 * look taken before the wait would replace that. When `check` returns a reason, nothing is
 * renamed and that reason is returned; null means the rename was made. `point` names the fault
 * point reached before each attempt (and `<point>-retry` before each further one); `on` is what
 * is called there.
 */
function renameOver(from, to, { check = null, point = 'rename', on = fault } = {}) {
  for (let attempt = 0; ; attempt++) {
    if (attempt) on(`${point}-retry`);
    const changed = check ? check() : null;
    if (changed) return changed;
    try { on(point); fs.renameSync(from, to); return null; } catch (e) {
      if (attempt >= 3 || !e || !(e.code === 'EPERM' || e.code === 'EBUSY' || e.code === 'EACCES')) throw e;
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 15 * (attempt + 1));
    }
  }
}

/** Make a rename inside `dir` durable. Best effort: not every filesystem lets a folder be synced. */
function syncFolder(dir) {
  if (IS_WIN) return;
  try { const d = fs.openSync(dir, 'r'); try { fs.fsyncSync(d); } finally { fs.closeSync(d); } } catch { /* best effort */ }
}

function putRecord(file, rec) {
  const tmp = tempName(file);
  stageFile(tmp, Buffer.from(JSON.stringify(rec, null, 2) + '\n', 'utf8'), 0o600, 'record');
  try { renameOver(tmp, file); } catch (e) {
    try { fs.unlinkSync(tmp); } catch { /* best effort */ }
    throw e;
  }
  syncFolder(path.dirname(file));
}

/**
 * Record what is about to be done, durably, BEFORE the first byte of it. A write names its
 * destination, the hash it has now and the hash it will have, its temp file, and every other
 * name of the file with the temp link made for it. An operation that only creates something
 * names the temp file or temp folder (`cleanup`) the next run has to remove if this one dies.
 * Every path comes with the real path and the identity of the folder it sits in, and the file
 * with its own identity: recovery acts only where all of that still holds (see settle).
 * Throws when the record cannot be written: then nothing is done at all.
 */
function openIntent(home, fields) {
  const dir = recoveryDir(home);
  const file = path.join(dir, `${Date.now().toString(36)}-${process.pid}-${crypto.randomBytes(3).toString('hex')}.json`);
  const rec = { version: INTENT_VERSION, tool: TOOL, pid: process.pid, startedAt: new Date().toISOString(), state: 'writing', ...fields };
  for (let attempt = 0; ; attempt++) {
    mkdirp(dir);
    try { putRecord(file, rec); break; } catch (e) {
      // Another run can remove the folder between the two calls, having just emptied it.
      if (!attempt && e && e.code === 'ENOENT') continue;
      try { fs.rmdirSync(dir); } catch { /* another record is open */ }
      throw e;
    }
  }
  return { file, rec };
}

function closeIntent(intent) {
  try { fs.unlinkSync(intent.file); } catch { /* the next run removes it */ }
  try { fs.rmdirSync(path.dirname(intent.file)); } catch { /* another record is open */ }
}

/** Every path a manifest records: where another name of a managed file can be. */
export function manifestPaths(manifest) {
  const out = [];
  for (const a of (manifest && Array.isArray(manifest.accounts) ? manifest.accounts : [])) {
    for (const e of Array.isArray(a.elements) ? a.elements : []) {
      if (e && typeof e.path === 'string') out.push(e.path);
      if (e && typeof e.target === 'string') out.push(e.target);
    }
  }
  return out;
}

/**
 * The paths among `candidates` that are OTHER names of the file at `real` (hardlinks to it),
 * each once, in its real spelling. A symbolic link to the file is not another name: it follows
 * the file by itself.
 */
function otherNames(real, candidates) {
  const seen = new Set([pathKey(real)]);
  const out = [];
  for (const c of candidates) {
    if (typeof c !== 'string' || !c) continue;
    const l = lstatSafe(c);
    if (!l || !l.isFile()) continue;
    const abs = realpathSafe(c);
    if (!abs || seen.has(pathKey(abs)) || !sameFile(abs, real)) continue;
    seen.add(pathKey(abs));
    out.push(abs);
  }
  return out;
}

/** The known other names of the file at `real`, and how many names it has beyond those. */
function namesOf(real, nlink, home, peers) {
  if (!(nlink > 1)) return { others: [], unknown: 0 };
  const others = otherNames(real, peers === undefined ? manifestPaths(readManifest(manifestFile(home))) : peers);
  return { others, unknown: Math.max(0, nlink - 1 - others.length) };
}

/** The refusal of a write to a file with `n` names nobody recorded (see writeKeepingLinks). */
export function unknownNamesError(n) {
  const [s, it, a] = n === 1 ? ['', 'it', 'a symbolic link'] : ['s', 'them', 'symbolic links'];
  return Object.assign(new Error(`the file has ${n} other name${s} (hardlink${s}) that this tool has no record of; replacing it would leave ${it} behind with the old content, so nothing was written. Remove ${it} or turn ${it} into ${a}, then run this again`), { code: 'EUNKNOWNNAMES', unknownNames: n });
}

/**
 * How many names the file at `p` has that writeKeepingLinks could not switch over: 0 means the
 * file can be written. `peers` as for writeKeepingLinks. For a caller that has to know before it
 * prepares anything.
 */
export function unknownNames(p, { home = homeDir(), peers } = {}) {
  const real = lstatSafe(p) ? realpathSafe(p) : null;
  const st = real ? statSafe(real) : null;
  return st && st.isFile() ? namesOf(real, st.nlink, home, peers).unknown : 0;
}

/**
 * Write a file so that no name of it ever holds torn bytes, and without breaking a link on it.
 *
 *   nothing at the path, or a file      temp file in the same folder, sync, atomic rename
 *   a symbolic link                     the link stays; the file it resolves to is replaced by
 *                                       these same rules
 *   a file with other names (hardlinks) the file is replaced as above, then each KNOWN other name
 *                                       is switched to the new file: a link to it is made under a
 *                                       temp name beside that name and renamed over it
 *
 * `peers` lists the paths where another name of the file may be (default: every path the
 * manifest records); only those that really are the same file count. When the file has more
 * names than that, NOTHING is written and the call throws with code `EUNKNOWNNAMES` and the
 * count in `unknownNames`: replacing the file would leave an unknown name behind with the old
 * content, and that is the user's decision.
 *
 * A record of the write is durable before its first byte (see openIntent), so a process that
 * dies at any point leaves each name with its complete old or its complete new bytes, and the
 * next run finishes the switch (see recoverWrites). On a failure before the rename this throws
 * with every name as it was.
 *
 * Nothing is replaced on the strength of what it was when the write was prepared. Right before
 * the rename over the file, and again right before each other name is switched, that path is
 * looked at once more: it must still be a plain file in the same real folder holding the same
 * bytes (see changedSince). That look is taken before EVERY attempt of a rename, so also after
 * each wait when a rename is refused for a moment (see renameOver). When the file itself changed,
 * nothing is written and the call throws with code `ECHANGED`. Another name that changed is left
 * exactly as it is and listed in `left`. What happens between that last look and the rename
 * cannot be seen: the window is two system calls wide, and it is not zero.
 * `expect` extends the look backwards: it is the hash the caller read the file with (null: the
 * file was not there) when it worked out the new bytes. A file that holds something else by the
 * time the write is prepared was changed in between, and is not written either (`ECHANGED`).
 *
 * Returns { how: 'created' | 'replaced', relinked, pending, why?, left? }: `pending` lists other
 * names that could not be switched just now (a file held open), for which the record stays and
 * the next run switches them; `left` lists [{ path, note }] for the names that were changed by
 * something else in the meantime. `at(point)` is for the tests: it is called at each point a
 * write passes (see `fault`), so a test can do there what another program might.
 */
export function writeKeepingLinks(p, data, { home = homeDir(), peers, at, expect } = {}) {
  const buf = Buffer.isBuffer(data) ? data : Buffer.from(String(data), 'utf8');
  const point = (name) => { if (at) at(name); fault(name); };
  let real = path.resolve(String(p));
  let st = null;
  if (lstatSafe(p)) {
    real = realpathSafe(p);
    if (!real) throw new Error('the path is a link to something that does not exist; nothing was written');
    st = fs.statSync(real);
    if (!st.isFile()) throw new Error('the path is not a file; nothing was written');
    // A rename needs no right on the file it replaces: one the user made read-only is left alone.
    fs.accessSync(real, fs.constants.W_OK);
  } else mkdirp(path.dirname(real));
  const { others, unknown } = namesOf(real, st ? st.nlink : 0, home, peers);
  if (unknown) throw unknownNamesError(unknown);
  const before = st ? hashFile(real) : null;
  if (st && before === null) throw new Error('the file cannot be read; nothing was written');
  if (expect !== undefined && before !== expect) {
    const how = !st ? 'it was removed' : expect === null ? 'something was created at its place' : 'it was edited';
    throw Object.assign(new Error(`the file changed while this write was being prepared (${how}); nothing was written`), { code: 'ECHANGED' });
  }
  // The record says where each name is (the real folder and its identity) and which file the
  // names are names of: what recovery needs to be sure it is looking at the same places.
  const intent = openIntent(home, {
    target: real, tmp: tempName(real), before, after: sha256(buf), id: st ? fileId(real) : null, ...placeOf(real),
    peers: others.map((o) => ({ path: o, tmp: tempName(o), ...placeOf(o) })),
  });
  const { rec } = intent;
  const made = [];
  try {
    point('intent');
    stageFile(rec.tmp, buf, st ? st.mode & 0o7777 : undefined, 'temp');
    made.push({ tmp: rec.tmp, owner: real, place: rec });
    point('staged');
    // A link to the NEW file, ready beside each other name: nothing anybody reads has changed yet.
    for (const pr of rec.peers) { fs.linkSync(rec.tmp, pr.tmp); made.push({ tmp: pr.tmp, owner: pr.path, place: pr }); point('peer-staged'); }
    // The one step that makes the path hold the new bytes, with the last look at the file right
    // before it, and before each further attempt.
    const changed = renameOver(rec.tmp, real, { check: () => changedSince(real, rec, before, !st), point: 'rename-file', on: point });
    if (changed) throw Object.assign(new Error(`the file changed while this write was being prepared (${changed}); nothing was written`), { code: 'ECHANGED' });
  } catch (e) {
    // A temp is removed only from the folder it was made in. If that folder was moved away or
    // redirected in the meantime, the same name now belongs to whatever is there.
    for (const m of made) { if (placeHolds(m.place, m.owner)) try { fs.unlinkSync(m.tmp); } catch { /* not there */ } }
    closeIntent(intent);
    // Whatever failed, say so in terms of the file when it is the file that changed meanwhile.
    const changed = e && e.code !== 'ECHANGED' ? changedSince(real, rec, before, !st) : null;
    throw changed ? Object.assign(new Error(`the file changed while this write was being prepared (${changed}); nothing was written`), { code: 'ECHANGED' }) : e;
  }
  point('committed');
  const pending = [];
  const left = [];
  let relinked = 0;
  let why;
  for (const pr of rec.peers) {
    try {
      point('peer');
      // The last look at this name, right before it is switched and before each further attempt:
      // one that something else changed since the write was prepared is not this tool's to replace.
      const changed = renameOver(pr.tmp, pr.path, { check: () => changedSince(pr.path, pr, before, false), point: 'rename-name', on: point });
      if (changed) {
        left.push({ path: pr.path, note: changed });
        if (placeHolds(pr, pr.path)) try { fs.unlinkSync(pr.tmp); } catch { /* not there */ }
        continue;
      }
      relinked++;
    } catch (e) { pending.push(pr.path); why = String(e && (e.code || e.message)); }
  }
  for (const d of new Set([real, ...rec.peers.map((pr) => pr.path)].map((f) => path.dirname(f)))) syncFolder(d);
  point('finished');
  if (pending.length) {
    // The path holds the new bytes; another name could not be switched (held open, on Windows).
    // The record stays, marked as waiting only for that: the next run finishes it.
    try { putRecord(intent.file, { ...rec, state: 'pending' }); } catch { /* the record as it is says the same */ }
  } else closeIntent(intent);
  return { how: st ? 'replaced' : 'created', relinked, pending, ...(why ? { why } : {}), ...(left.length ? { left } : {}) };
}

/** True when `p` is a plain file itself: not a link to one. */
function isPlainFile(p) {
  const l = lstatSafe(p);
  return !!l && l.isFile();
}

/** The identity of a file where the filesystem gives a stable one: `dev:ino`, or null. */
function fileId(p) {
  try { const s = fs.lstatSync(p, { bigint: true }); return s.ino === 0n ? null : `${s.dev}:${s.ino}`; } catch { return null; }
}

/**
 * Where a path is: the real path of the folder it sits in (or would be created in) and, where
 * the filesystem gives one, the identity of that folder. A path is "the same place" only while
 * both still hold: equal bytes behind a folder that was moved, replaced or redirected prove
 * nothing.
 */
export function placeOf(p) {
  const parent = realParent(p);
  return { parent, parentId: parent ? fileId(parent) : null };
}

/** True when `p` still sits in the folder recorded in `place` (see placeOf). */
export function placeHolds(place, p) {
  if (!place || typeof place.parent !== 'string' || !place.parent) return false;
  const now = placeOf(p);
  if (!now.parent || pathKey(now.parent) !== pathKey(place.parent)) return false;
  return !place.parentId || now.parentId === place.parentId;
}

/**
 * Why `file` is no longer what it was when a write was prepared, or null when it still is: a
 * plain file (with `absent`: still nothing) in the same real folder, holding the bytes of
 * `hash`. The file is looked at before and after it is read, so a change during the read shows
 * too. Called right before the rename that replaces `file`; nothing can be said about what
 * happens between this and that rename.
 */
function changedSince(file, place, hash, absent) {
  if (!placeHolds(place, file)) return 'its folder was moved, replaced or redirected';
  let a;
  try { a = fs.lstatSync(file, { bigint: true }); } catch { return absent ? null : 'it was removed'; }
  if (absent) return 'something was created at its place';
  if (!a.isFile()) return 'it was replaced by something that is not a plain file';
  const now = hashFile(file);
  let b;
  try { b = fs.lstatSync(file, { bigint: true }); } catch { return 'it was removed'; }
  if (now !== hash || a.ino !== b.ino || a.size !== b.size || a.mtimeNs !== b.mtimeNs) return 'it was edited';
  return null;
}

/**
 * Make something appear at `dst` whole or not at all: `build(tmp)` creates it under a temp name
 * beside `dst` (a file, or a folder with anything in it), and the temp is then renamed to `dst`.
 * A record lets the next run remove the temp if this one dies. `dst` must not be a folder that
 * exists already.
 */
export function buildThenRename(dst, build, { home = homeDir(), at } = {}) {
  const tmp = tempName(dst);
  const place = placeOf(tmp);
  const intent = openIntent(home, { cleanup: [{ path: tmp, ...place }] });
  const on = (name) => { if (at) at(name); fault(name); };
  try {
    build(tmp);
    // Before every attempt: the folder is still the one the temp was made in, and nothing has
    // appeared under the name in the meantime.
    const still = () => (!placeHolds(place, dst) ? 'its folder was moved, replaced or redirected' : lstatSafe(dst) ? 'something was created at its place' : null);
    const changed = renameOver(tmp, dst, { check: still, point: 'rename-temp', on });
    if (changed) throw Object.assign(new Error(`the place changed while this was being made (${changed}); nothing was put there`), { code: 'ECHANGED' });
  } catch (e) {
    if (placeHolds(place, tmp)) removeTemp(tmp); // only from the folder it was made in
    throw e;
  } finally { closeIntent(intent); }
}

/** Copy a file so that `dst` never shows half of it. */
export function copyFileSafe(src, dst, { home = homeDir(), at } = {}) {
  buildThenRename(dst, (tmp) => { fs.copyFileSync(src, tmp); fault('copied'); }, { home, at });
}

/**
 * Remove a temp file, or a temp folder with everything in it. A link is removed as a link and
 * never followed. Only ever called on a path this tool named as a temp (see TEMP_RE).
 */
function removeTemp(p) {
  const l = lstatSafe(p);
  if (!l) return false;
  try {
    if (l.isDirectory() && !l.isSymbolicLink()) {
      for (const e of readdirSafe(p)) removeTemp(path.join(p, e.name));
      fs.rmdirSync(p);
    } else removeLink(p);
    return true;
  } catch { return false; }
}

/** Deal with one record a dead run left. Returns what was found, or null when there was nothing. */
function settle(rec, file, home, repair, at) {
  const show = (p) => displayPath(p, home);
  const on = (name) => { if (at) at(name); fault(name); };
  // Only ever a temp file of this tool is removed or renamed, whatever a record says, and only
  // where it was made: beside the path it was made for, in the folder recorded for that path.
  // Equal bytes are no proof of a place: a folder that was moved away and replaced by a link to
  // another one can hold a file with the very same content.
  const ours = (p) => typeof p === 'string' && path.isAbsolute(p) && TEMP_RE.test(p);
  const beside = (tmp, owner, place) => ours(tmp) && typeof owner === 'string' && path.isAbsolute(owner)
    && pathKey(path.dirname(path.resolve(tmp))) === pathKey(path.dirname(path.resolve(owner))) && placeHolds(place, owner);
  const drop = (tmp) => (removeTemp(tmp) ? 1 : 0);
  const done = () => { try { fs.unlinkSync(file); } catch { /* tried again by the next run */ } };
  const elsewhere = 'its folder is not the one the write was made in (moved, replaced or redirected since)';
  if (typeof rec.target !== 'string' || !path.isAbsolute(rec.target) || typeof rec.after !== 'string') {
    // Not a write: something was being created, and only its temp file or temp folder can be left.
    const found = (Array.isArray(rec.cleanup) ? rec.cleanup : []).filter((c) => c && ours(c.path) && lstatSafe(c.path));
    const here = found.filter((c) => beside(c.path, c.path, c));
    const foreign = found.filter((c) => !here.includes(c));
    if (!repair) return found.length ? { file: show(found[0].path), outcome: 'pending', leftovers: found.length } : null;
    let n = 0;
    for (const c of here) n += drop(c.path);
    done();
    // What sits under that name in another folder is not this tool's to remove: said once.
    if (foreign.length) return { file: show(foreign[0].path), outcome: 'conflict', note: elsewhere, ...(n ? { leftovers: n } : {}) };
    return n ? { file: show(here[0].path), outcome: 'removed', leftovers: n } : null;
  }
  const entry = { file: show(rec.target) };
  if (!repair) return { ...entry, outcome: 'pending' };
  // The file itself first. While its folder is not the one the write was made in, nothing can be
  // told (the file read there would be another file) and nothing is touched; the record stays,
  // so that the write is settled once the folder is back.
  const sound = ours(rec.tmp) && typeof rec.parent === 'string' && !!rec.parent
    && pathKey(path.dirname(path.resolve(rec.tmp))) === pathKey(path.dirname(path.resolve(rec.target)));
  if (!sound) { done(); return { file: show(file), outcome: 'removed', note: 'a record that cannot be used' }; }
  if (!placeHolds(rec, rec.target)) return { ...entry, outcome: 'conflict', note: elsewhere, record: show(file) };
  const peers = (Array.isArray(rec.peers) ? rec.peers : []).filter((pr) => pr && typeof pr.path === 'string' && path.isAbsolute(pr.path));
  let lt = null;
  try { lt = fs.lstatSync(rec.target, { bigint: true }); } catch { /* not there */ }
  const now = lt && lt.isFile() ? hashFile(rec.target) : null;
  if (lt && lt.isFile() && now !== null && now === rec.after) {
    // The rename went through: the path holds the new bytes. Each other name is switched over
    // when it is still, provably, the name the dead run was about to switch: in its recorded
    // folder, still a name of the old file, still holding the old bytes, and with the link the
    // dead run made for it (a link to this very file) waiting beside it. Anything else is left.
    let relinked = 0;
    let left = 0;
    let foreign = 0;
    let waiting = 0;
    let why;
    for (const pr of peers) {
      // What this name is, asked right before every attempt to switch it (see renameOver): the
      // name, its folder, or the file itself can change during a wait between two attempts.
      const state = () => {
        if (!beside(pr.tmp, pr.path, pr)) return 'foreign'; // another folder now: nothing there is touched
        let l = null;
        try { l = fs.lstatSync(pr.path, { bigint: true }); } catch { /* gone */ }
        if (l && l.isFile() && sameFile(pr.path, rec.target)) return 'switched';
        const whole = placeHolds(rec, rec.target) && isPlainFile(rec.target) && hashFile(rec.target) === rec.after;
        const old = !!l && l.isFile() && (!rec.id || `${l.dev}:${l.ino}` === rec.id) && hashFile(pr.path) === rec.before;
        const link = lstatSafe(pr.tmp);
        return whole && old && link && link.isFile() && sameFile(pr.tmp, rec.target) ? 'ok' : 'left';
      };
      let s = state();
      if (s === 'ok') {
        try {
          const stopped = renameOver(pr.tmp, pr.path, { check: () => { s = state(); return s === 'ok' ? null : s; }, point: 'rename-recovery', on });
          if (!stopped) s = 'relinked';
        } catch (e) { s = 'waiting'; why = scrub(String(e && (e.code || e.message)), home); }
      }
      if (s === 'foreign') foreign++;
      else if (s === 'relinked') relinked++;
      else if (s === 'waiting') waiting++;
      else { drop(pr.tmp); if (s === 'left') left++; }
    }
    drop(rec.tmp);
    const counts = { ...(relinked ? { relinked } : {}), ...(left ? { left } : {}), ...(foreign ? { foreign } : {}) };
    if (waiting) {
      if (rec.state !== 'pending') try { putRecord(file, { ...rec, state: 'pending' }); } catch { /* it says the same */ }
      return { ...entry, outcome: 'waiting', waiting, ...counts, note: why };
    }
    done();
    return { ...entry, outcome: 'completed', ...counts };
  }
  // The rename never happened (the path holds what it held), or the file was changed since:
  // either way no name is touched, and only the temp files go, each from its recorded folder.
  const untouched = lt ? lt.isFile() && now !== null && now === rec.before : rec.before === null;
  drop(rec.tmp);
  let foreign = 0;
  for (const pr of peers) { if (beside(pr.tmp, pr.path, pr)) drop(pr.tmp); else foreign++; }
  done();
  return { ...entry, outcome: untouched ? 'rolled-back' : 'abandoned', ...(foreign ? { foreign } : {}) };
}

/**
 * Finish, or clear, what a run that died in the middle of a write left behind. Every run that
 * may write calls this first; a read-only one passes `repair: false` and only learns what is
 * waiting. Returns one entry per thing found, `file` as a display path, with `outcome`:
 *   completed    the path had its new bytes: the other names still holding the old ones were
 *                switched over (`relinked`); one changed since, or gone, was left (`left`)
 *   rolled-back  the write had not taken effect: every name is as it was, the temp files are gone
 *   abandoned    the file was changed since: no name was touched, the temp files are gone
 *   waiting      another name still cannot be switched (`note` says why); tried again next run
 *   removed      temp files of an operation that only creates things, or of this tool's own
 *                bookkeeping, were removed (`leftovers`)
 *   conflict     a folder is not the one the write was made in (moved, replaced, redirected):
 *                nothing in it was read, linked, renamed or removed. With `record`, it is the
 *                folder of the file itself: the record is kept and this is said at every run
 *                until the folder is back or the record is deleted
 *   pending      found, nothing touched (`repair: false`)
 * `foreign` on any entry counts the other names of the file that sit in such a folder: they
 * were left alone, with whatever is there.
 * A temp file of the tool's own bookkeeping is a leftover once it is a minute old. Never throws.
 */
export function recoverWrites({ home = homeDir(), repair = true, at } = {}) {
  const out = [];
  const show = (p) => displayPath(p, home);
  try {
    const dir = recoveryDir(home);
    let names = null;
    try { names = fs.readdirSync(dir).sort(); } catch { /* the usual case: no such folder */ }
    for (const name of names || []) {
      if (!name.endsWith('.json')) continue;
      const file = path.join(dir, name);
      const j = parseJson(readText(file, 1024 * 1024));
      const rec = j.ok && j.value && typeof j.value === 'object' && j.value.version === INTENT_VERSION ? j.value : null;
      let entry;
      if (rec) {
        try { entry = settle(rec, file, home, repair, at); } catch (e) { entry = { file: show(file), outcome: 'waiting', note: scrub(String(e && (e.code || e.message)), home) }; }
      } else {
        if (repair) try { fs.unlinkSync(file); } catch { /* tried again by the next run */ }
        entry = { file: show(file), outcome: repair ? 'removed' : 'pending', note: 'a record that cannot be read' };
      }
      if (entry) out.push(entry);
    }
    // Temp files of the tool's own bookkeeping (manifest, journals, these records): all of them
    // are made at the top of the sync folder or in the recovery folder.
    for (const d of names ? [syncDir(home), dir] : [syncDir(home)]) {
      for (const name of readdirSafe(d).map((e) => e.name).filter((n) => TEMP_RE.test(n)).sort()) {
        const p = path.join(d, name);
        const st = lstatSafe(p);
        if (!st || Math.abs(Date.now() - st.mtimeMs) < LEFTOVER_AGE_MS) continue; // a run may be using it
        if (repair) { try { fs.unlinkSync(p); } catch { continue; } }
        out.push({ file: show(p), outcome: repair ? 'removed' : 'pending', leftovers: 1 });
      }
    }
    if (repair && names) try { fs.rmdirSync(dir); } catch { /* a record is still there */ }
  } catch { /* recovery never stops a run */ }
  return out;
}

/** One entry of recoverWrites as a short sentence. */
export function recoveryText(r) {
  const names = (n) => `${n} other name${n === 1 ? '' : 's'} of the file`;
  const foreign = r.foreign ? `; ${names(r.foreign)} ${r.foreign === 1 ? 'sits' : 'sit'} in a folder that was moved, replaced or redirected since, and ${r.foreign === 1 ? 'was' : 'were'} left alone` : '';
  if (r.outcome === 'completed') {
    return `${r.file}: an interrupted write had gone through${r.relinked ? `; ${names(r.relinked)} now follow${r.relinked === 1 ? 's' : ''} it` : ''}${r.left ? `; ${names(r.left)} changed since and ${r.left === 1 ? 'was' : 'were'} left` : ''}${foreign}`;
  }
  if (r.outcome === 'rolled-back') return `${r.file}: an interrupted write had not gone through; the file is as it was${foreign}`;
  if (r.outcome === 'abandoned') return `${r.file}: an interrupted write was dropped, because the file changed since${foreign}`;
  if (r.outcome === 'conflict') return `${r.file}: left as it is, because ${r.note}${r.record ? `; put the folder back, or delete ${r.record}` : ''}`;
  if (r.outcome === 'waiting') return `${r.file}: ${r.waiting ? `${names(r.waiting)} could not be switched over yet` : 'an interrupted write could not be finished yet'} (${r.note})`;
  if (r.outcome === 'removed') return `${r.file}: ${r.note || (r.leftovers > 1 ? `${r.leftovers} leftover temp files` : 'a leftover temp file')} removed`;
  return `${r.file}: left unfinished by an interrupted run (a check with --repair deals with it)`;
}

/** The real path of the folder a file sits in, or would be created in when folders are missing. */
function realParent(p) {
  const rest = [];
  for (let d = path.dirname(path.resolve(String(p))); ; d = path.dirname(d)) {
    const r = realpathSafe(d);
    if (r) return path.join(r, ...rest);
    if (path.dirname(d) === d) return null;
    rest.unshift(path.basename(d));
  }
}

/**
 * What a write to `p` would land on: the kind of thing at the path (`none` when nothing is
 * there), the real path of the file and of its folder, how many names the file has, and the
 * volume and file ids where the filesystem reports them. The ids are read as bigints and kept as
 * strings, because a Windows file id does not fit a double. `ids: false` leaves them out, for a
 * file its own app replaces at every save.
 */
export function destIdentity(p, { ids = true } = {}) {
  const parent = realParent(p);
  let l;
  try { l = fs.lstatSync(p, { bigint: true }); } catch { return { type: 'none', parent }; }
  const type = l.isSymbolicLink() ? 'symlink' : l.isFile() ? 'file' : l.isDirectory() ? 'dir' : 'other';
  const out = { type, parent, real: realpathSafe(p) };
  let st = l;
  if (type === 'symlink') { try { st = fs.statSync(p, { bigint: true }); } catch { st = null; } }
  if (st) {
    out.nlink = Number(st.nlink);
    if (ids && st.ino !== 0n) { out.dev = String(st.dev); out.ino = String(st.ino); }
  }
  return out;
}

/**
 * Why an UNATTENDED write to `p` must not happen, as a short sentence, or null when it may.
 * The check writes only to a plain file that has no other name (or re-creates a missing one),
 * in the folder recorded for it, inside the account folder. So it refuses when the path became
 * a link, gained a hardlink, or when a folder above it now leads somewhere else: the write would
 * land on a destination nobody approved. `rec` is the identity recorded when the file was
 * generated. A manifest written before identities were recorded has none: the path is then
 * accepted only when nothing from the account folder down is a link.
 *
 * A changed file id alone is NOT a reason to refuse. Every editor or app that saves a file
 * replaces it, and because the check writes through a rename it cannot reach into another file:
 * a plain, single-name file in the recorded folder is safe to replace whichever inode it has.
 */
export function destinationProblem(rec, p, accountDir) {
  const cur = destIdentity(p);
  const accountReal = realpathSafe(accountDir);
  if (!accountReal || !cur.parent) return 'its folder cannot be resolved';
  if (cur.type === 'symlink') return rec && rec.type === 'symlink' ? 'it is a link, which only a plan and apply write through' : 'it became a link to another place';
  if (cur.type !== 'file' && cur.type !== 'none') return 'it is not a file any more';
  if (cur.type === 'file' && cur.nlink > 1) return 'it now shares its content with another file (a hardlink)';
  let expected = rec && rec.parent ? rec.parent : null;
  if (!expected) {
    const l = lstatSafe(accountDir);
    if (!l || l.isSymbolicLink() || !isInside(p, accountDir)) return 'its place was never recorded and cannot be confirmed (plan and apply again)';
    expected = path.join(accountReal, path.relative(path.resolve(accountDir), path.dirname(path.resolve(String(p)))));
  }
  if (pathKey(cur.parent) !== pathKey(expected) || !isInside(cur.parent, accountReal)) {
    return isInside(cur.parent, accountReal) ? 'its folder now leads somewhere else' : 'its folder now leads outside the account folder';
  }
  return null;
}

/** Write through a temp file and rename: for files this tool owns (manifest, journals). */
export function writeAtomic(p, data, { via, durable = false } = {}) {
  // `via`: the folder where the temp file is made. The tool keeps every temp file of its own
  // bookkeeping at the top of its sync folder, so that one look there finds what a dead run left.
  // `durable`: synced to disk before this returns, for a journal entry that has to be there
  // BEFORE the action it describes.
  mkdirp(path.dirname(p));
  const put = (tmp) => {
    try {
      if (durable) stageFile(tmp, Buffer.isBuffer(data) ? data : Buffer.from(String(data), 'utf8'), undefined, 'journal');
      else fs.writeFileSync(tmp, data);
      renameOver(tmp, p);
      if (durable) syncFolder(path.dirname(p));
    } catch (e) {
      try { fs.unlinkSync(tmp); } catch { /* best effort */ }
      throw e;
    }
  };
  if (!via) { put(tempName(p)); return; }
  try { put(tempName(path.join(via, path.basename(p)))); } catch (e) {
    if (!e || (e.code !== 'EXDEV' && e.code !== 'ENOENT')) throw e;
    put(tempName(p)); // that folder is on another volume, or gone: beside the file, then
  }
}

// ---------------------------------------------------------------------------------------------
// Links
// ---------------------------------------------------------------------------------------------

/**
 * How `linkPath` relates to `targetPath`:
 *   ok          resolves to the target (symlink, junction, hardlink, or through a linked parent)
 *   missing     nothing at linkPath
 *   dangling    a link to the expected target, which no longer exists
 *   other-link  a link that points somewhere else
 *   not-link    a real file or directory
 */
export function linkStatus(linkPath, targetPath) {
  const l = lstatSafe(linkPath);
  if (!l) return { state: 'missing' };
  const rp = realpathSafe(linkPath);
  const rt = realpathSafe(targetPath);
  if (l.isSymbolicLink()) {
    if (rp && rt && pathKey(rp) === pathKey(rt)) return { state: 'ok', kind: 'symlink' };
    if (!rp) {
      const raw = readlinkSafe(linkPath);
      const abs = raw ? path.resolve(path.dirname(linkPath), raw) : null;
      if (abs && pathKey(abs) === pathKey(targetPath)) return { state: 'dangling', kind: 'symlink' };
      return { state: 'other-link', kind: 'symlink', dangling: true };
    }
    return { state: 'other-link', kind: 'symlink' };
  }
  if (rp && rt && pathKey(rp) === pathKey(rt)) return { state: 'ok', kind: 'inherited' };
  if (l.isFile() && sameFile(linkPath, targetPath)) return { state: 'ok', kind: 'hardlink' };
  return { state: 'not-link', kind: l.isDirectory() ? 'dir' : 'file' };
}

const SYMLINK_REFUSED = new Set(['EPERM', 'EACCES', 'ENOSYS', 'UNKNOWN', 'ENOTSUP']);

/**
 * Link `linkPath` to `targetPath`. Prefers a symbolic link. Where the OS refuses one (Windows
 * without the privilege), a directory becomes a junction and a file becomes a hardlink.
 * Returns the kind created. The tests force the fallbacks with NOVARC_POWERS_NO_SYMLINK:
 * `1` refuses symbolic links, `2` also refuses hardlinks (as across volumes).
 */
export function createLink(targetPath, linkPath, isDirectory) {
  mkdirp(path.dirname(linkPath));
  if (!process.env.NOVARC_POWERS_NO_SYMLINK) {
    try {
      fs.symlinkSync(targetPath, linkPath, isDirectory ? 'dir' : 'file');
      return 'symlink';
    } catch (e) {
      if (!SYMLINK_REFUSED.has(e.code)) throw e;
    }
  }
  if (isDirectory) {
    fs.symlinkSync(targetPath, linkPath, 'junction'); // the type is ignored outside Windows
    return IS_WIN ? 'junction' : 'symlink';
  }
  if (process.env.NOVARC_POWERS_NO_SYMLINK === '2') {
    // Tests only: behave as when the two folders are on different volumes.
    throw Object.assign(new Error('cross-device link not permitted'), { code: 'EXDEV' });
  }
  fs.linkSync(realpathSafe(targetPath) || targetPath, linkPath);
  return 'hardlink';
}

const NO_LINK = new Set(['EXDEV', 'EPERM', 'EACCES', 'EMLINK', 'ENOTSUP']);

/**
 * Link, or for a file that cannot be linked at all (the folders are on different volumes, or the
 * filesystem has no links) make a managed copy. Returns the kind, `copy` for the last case.
 */
export function linkOrCopy(targetPath, linkPath, isDirectory, home = homeDir()) {
  try { return createLink(targetPath, linkPath, isDirectory); } catch (e) {
    if (isDirectory || !NO_LINK.has(e.code)) throw e;
    copyFileSafe(targetPath, linkPath, { home });
    return 'copy';
  }
}

/** The manifest record of a linked element. A managed copy is tracked like a generated file. */
export function linkRecord(name, kind, linkPath, targetPath, isDirectory) {
  // `place`: the folder the link sits in. The unattended check repairs the link only there.
  if (isDirectory) return { name, kind, path: linkPath, target: targetPath, dir: true, place: placeOf(linkPath) };
  const hash = hashFile(targetPath);
  if (kind === 'copy') return { name, kind: 'generated', path: linkPath, target: targetPath, generator: { type: 'copy' }, sourceHash: hash, contentHash: hash, identity: destIdentity(linkPath) };
  return { name, kind, path: linkPath, target: targetPath, contentHash: hash, place: placeOf(linkPath) };
}

/** A folder as the manifest records it: its real path and, where there is one, its identity. */
export function folderIdentity(dir) {
  const real = realpathSafe(dir);
  return { real, id: real ? fileId(real) : null };
}

/**
 * Why nothing may be repaired in an account, or null. The manifest records where the account
 * folder really is (`dir`). When its name now leads to another folder (it was moved away and a
 * link, or a new folder, took the name), whatever is there is not the account that was synced,
 * identical files or not. A manifest from before that was recorded is accepted, and completed,
 * only while the folder is plainly itself: not a link.
 */
function accountMoved(acct, repair) {
  const now = folderIdentity(acct.pathAbs);
  if (acct.dir && typeof acct.dir.real === 'string') {
    const same = !!now.real && pathKey(now.real) === pathKey(acct.dir.real) && (!acct.dir.id || acct.dir.id === now.id);
    return same ? null : 'the account folder was moved, replaced or redirected since it was synced; nothing in it is repaired (plan and apply again)';
  }
  const l = lstatSafe(acct.pathAbs);
  if (!l || l.isSymbolicLink() || !now.real) return 'the account folder is a link, and where it led when it was synced was never recorded; nothing in it is repaired (plan and apply again)';
  if (repair) acct.dir = now;
  return null;
}

/** Remove a link (or a plain file). Never recurses into a directory. */
export function removeLink(p) {
  try { fs.unlinkSync(p); } catch (e) {
    if (e.code === 'ENOENT') return;
    fs.rmdirSync(p); // a directory symlink or junction on platforms where unlink refuses it
  }
}

/** Replace the file at linkPath with a link to targetPath without a window where it is missing. */
export function relinkFile(targetPath, linkPath, home = homeDir(), expect = null) {
  // `expect`: { hash, place } of the file as it was when it was judged safe to replace (a copy
  // nobody edited). It is looked at again before every attempt of the rename: one that changed
  // since is not replaced, and the call throws with code `ECHANGED`.
  const tmp = tempName(linkPath);
  const place = placeOf(tmp);
  const intent = openIntent(home, { cleanup: [{ path: tmp, ...place }] });
  try {
    const kind = createLink(targetPath, tmp, false);
    let changed;
    try {
      fault('linked');
      changed = renameOver(tmp, linkPath, { check: expect ? () => changedSince(linkPath, expect.place || place, expect.hash, false) : null, point: 'rename-link' });
    } catch (e) {
      try { fs.unlinkSync(tmp); } catch { /* best effort */ }
      throw e;
    }
    if (changed) {
      if (placeHolds(place, tmp)) try { fs.unlinkSync(tmp); } catch { /* best effort */ }
      throw Object.assign(new Error(`the file changed while it was being linked again (${changed}); it was left as it is`), { code: 'ECHANGED' });
    }
    return kind;
  } finally { closeIntent(intent); }
}

// ---------------------------------------------------------------------------------------------
// Instruction files: @imports, provider fences, generation
// ---------------------------------------------------------------------------------------------

/**
 * Top-level names of a config dir that are never linked, copied, generated from or read:
 * credentials, account state, sessions, history, caches, and account-local settings.
 */
const NEVER_TOP = new Set([
  '.credentials.json', '.claude.json', 'auth.json', 'settings.local.json', 'projects', 'todos',
  'shell-snapshots', 'statsig', 'sessions', 'session-env', 'file-history', 'paste-cache', 'ide',
  'cache', 'caches', 'logs', 'log', 'telemetry', 'debug', 'tmp', 'backups', 'memories',
]);
const NEVER_TOP_RE = /^(history|\.claude\.json|\.credentials)|cache|\.(sqlite3?|db|log|lock)$/i;

export function isNeverTop(name) {
  const n = String(name).toLowerCase();
  return NEVER_TOP.has(n) || NEVER_TOP_RE.test(n);
}

/** File names that are never read, inlined, linked or copied, whatever points at them. */
export const NEVER_FILE = /^(\.credentials\.json|\.claude\.json(\..*)?|auth\.json|settings\.local\.json|\.env(\..*)?|.*\.(pem|key|p12|pfx|sqlite3?|db|log))$/i;

const CODE_FENCE = /^\s*(`{3,}|~{3,})/;
const IMPORT_RE = /(^|[\s(])@((?:~|\.{1,2})?[\\/]?[^\s`'"()<>[\]{}]+)/g;

/** `@path` imports in one markdown line (inline code spans ignored). */
export function importsInLine(line) {
  const masked = line.replace(/`[^`\n]*`/g, (m) => ' '.repeat(m.length));
  const out = [];
  IMPORT_RE.lastIndex = 0;
  let m;
  while ((m = IMPORT_RE.exec(masked)) !== null) {
    const raw = m[2].replace(/[.,;:!?]+$/, '');
    if (!raw || raw.includes('@')) continue;
    const pathish = /^(~[\\/]|\.{1,2}[\\/]|[\\/]|[A-Za-z]:[\\/])/.test(raw);
    const hasExt = /\.[A-Za-z0-9]{1,8}$/.test(raw);
    if (!pathish && !hasExt) continue; // `@name` mentions and package scopes are not imports
    out.push({ raw });
  }
  return out;
}

/** Walk the lines of a markdown text, telling the callback which ones belong to a code fence. */
function eachLine(text, fn) {
  let fence = null;
  for (const line of text.split('\n')) {
    const cf = CODE_FENCE.exec(line);
    if (cf) {
      const mark = cf[1];
      if (!fence) { fence = mark; fn(line, true); continue; }
      if (mark[0] === fence[0] && mark.length >= fence.length) { fence = null; fn(line, true); continue; }
    }
    fn(line, fence !== null);
  }
}

export function resolveImport(raw, fromFile, home = homeDir()) {
  if (raw === '~') return home;
  if (raw.startsWith('~/') || raw.startsWith('~\\')) return path.join(home, raw.slice(2));
  if (path.isAbsolute(raw)) return path.normalize(raw);
  return path.resolve(path.dirname(fromFile), raw);
}

/**
 * Every file an instruction file imports, following imports up to 5 hops (as Claude Code does).
 * Imports resolve relative to the importing file's own folder. Returns absolute paths of files
 * that exist, without the root file.
 */
export function collectImports(rootFile, { home = homeDir(), maxDepth = 5 } = {}) {
  const seen = new Set([pathKey(rootFile)]);
  const out = [];
  const visit = (file, depth) => {
    const text = readText(file, 1024 * 1024);
    if (text === null) return;
    eachLine(text.replace(/\r\n?/g, '\n'), (line, inCode) => {
      if (inCode) return;
      for (const imp of importsInLine(line)) {
        const abs = resolveImport(imp.raw, file, home);
        const key = pathKey(abs);
        if (seen.has(key) || NEVER_FILE.test(path.basename(abs)) || !isFile(abs)) continue;
        seen.add(key);
        out.push(abs);
        if (depth < maxDepth) visit(abs, depth + 1);
      }
    });
  };
  visit(rootFile, 1);
  return out;
}

function normProvider(p) {
  const s = String(p || '').trim().toLowerCase();
  return s === 'claude' ? 'claude-code' : s;
}

function providerListed(list, provider) {
  return String(list).split(/[,\s]+/).filter(Boolean).map(normProvider).includes(normProvider(provider));
}

const FENCE_OPEN = /^\s*<!--\s*(only|except)\s*:\s*([^>]*?)\s*-->\s*$/i;
const FENCE_CLOSE = /^\s*<!--\s*\/\s*(only|except)\s*-->\s*$/i;
const FENCE_INLINE = /<!--\s*(only|except)\s*:\s*([^>]*?)\s*-->(.*?)<!--\s*\/\s*\1\s*-->/gi;

/**
 * Honour provider fences. Text between `<!-- only: claude-code -->` and `<!-- /only -->` is kept
 * only for the listed providers; text between `<!-- except: codex -->` and `<!-- /except -->` is
 * dropped for them. The fence lines themselves never reach the output. Fences nest.
 */
export function applyProviderFences(text, provider) {
  const out = [];
  const stack = [];
  let dropped = false;
  const push = (line) => {
    const blank = line.trim() === '';
    if (dropped && blank && (!out.length || out[out.length - 1].trim() === '')) { dropped = false; return; }
    dropped = false;
    out.push(line);
  };
  eachLine(text, (line, inCode) => {
    const keeping = stack.every((f) => f);
    if (inCode) { if (keeping) push(line); return; }
    const open = FENCE_OPEN.exec(line);
    if (open) { stack.push((open[1].toLowerCase() === 'only') === providerListed(open[2], provider)); return; }
    if (FENCE_CLOSE.test(line)) { if (stack.length && !stack.pop()) dropped = true; return; }
    if (!keeping) return;
    push(line.replace(FENCE_INLINE, (all, kind, list, body) => ((kind.toLowerCase() === 'only') === providerListed(list, provider) ? body : '')));
  });
  return out.join('\n');
}

/**
 * Build another provider's instruction file from the primary's: a first-line marker comment,
 * provider fences honoured, and (when the source format has imports) every `@import` replaced in
 * place by the imported file's content. Returns null when the source cannot be read.
 */
export function generateInstructions({ source, provider, sourceDisplay, inlineImports = true, home = homeDir() }) {
  const inputs = [];
  const unresolved = [];
  const render = (file, depth, stack) => {
    const raw = readText(file, 1024 * 1024);
    if (raw === null) return null;
    inputs.push(file);
    const text = applyProviderFences(stripBom(raw).replace(/\r\n?/g, '\n'), provider);
    if (!inlineImports) return text;
    const out = [];
    eachLine(text, (line, inCode) => {
      const imports = inCode ? [] : importsInLine(line);
      if (!imports.length) { out.push(line); return; }
      const blocks = [];
      for (const imp of imports) {
        const abs = resolveImport(imp.raw, file, home);
        const key = pathKey(abs);
        if (depth >= 5 || stack.includes(key) || NEVER_FILE.test(path.basename(abs)) || !isFile(abs)) { unresolved.push(imp.raw); continue; }
        const body = render(abs, depth + 1, [...stack, key]);
        if (body === null) { unresolved.push(imp.raw); continue; }
        blocks.push(`<!-- import: ${imp.raw} -->\n${body.replace(/\n+$/, '')}\n<!-- /import -->`);
      }
      const alone = imports.length === 1 && blocks.length === 1 && /^\s*(?:[-*+]\s+)?@\S+\s*$/.test(line);
      if (!alone) out.push(line);
      for (const b of blocks) out.push(b);
    });
    return out.join('\n');
  };
  const body = render(source, 0, [pathKey(source)]);
  if (body === null) return null;
  const text = `${GENERATED_PREFIX}${sourceDisplay}; edit the primary and run the sync check -->\n${body.replace(/\n+$/, '')}\n`;
  return { text, inputs, unresolved };
}

// ---------------------------------------------------------------------------------------------
// MCP servers: inline secrets, a neutral shape, Claude JSON <-> Codex TOML
// ---------------------------------------------------------------------------------------------

const TOKEN_RES = [
  /-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY/,
  /\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{36,}\b/,
  /\bgithub_pat_[A-Za-z0-9_]{22,}\b/,
  /\bsk-(?:ant-|proj-|svcacct-|admin-|live-|test-)?[A-Za-z0-9_-]{20,}/,
  /\b(?:sk|rk)_live_[A-Za-z0-9]{16,}\b/,
  /\bsbp_[A-Za-z0-9]{20,}\b/,
  /\bxox[abpr]-[A-Za-z0-9-]{10,}/,
  /\bnpm_[A-Za-z0-9]{36}\b/,
  /\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/,
  /\bAIza[A-Za-z0-9_-]{35}\b/,
  /\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\./,
  /\bBearer\s+[A-Za-z0-9._~+/=-]{12,}/i,
];
const SECRET_KEY = /(token|secret|passw(or)?d|pwd|api[_-]?key|apikey|access[_-]?key|private[_-]?key|credential|authorization|bearer|cookie)/i;
const ENV_REF = /^(\$\{[A-Za-z_][A-Za-z0-9_]*(:-[^}]*)?\}|\$[A-Za-z_][A-Za-z0-9_]*|%[A-Za-z_][A-Za-z0-9_]*%)$/;
const HAS_REF = /\$\{[A-Za-z_][A-Za-z0-9_]*(:-[^}]*)?\}/;
const LOOKS_LIKE_PATH = /^(~|\.{1,2})?[\\/]|^[A-Za-z]:[\\/]/;

function literalLooksSecret(value) {
  if (typeof value !== 'string' || !value || ENV_REF.test(value)) return false;
  return TOKEN_RES.some((re) => re.test(value));
}

function namedSecret(key, value) {
  if (typeof value !== 'string' || value.length < 8 || HAS_REF.test(value) || ENV_REF.test(value)) return false;
  if (LOOKS_LIKE_PATH.test(value)) return false;
  return SECRET_KEY.test(key);
}

function opaqueLiteral(value) {
  if (typeof value !== 'string' || value.length < 32 || HAS_REF.test(value) || LOOKS_LIKE_PATH.test(value)) return false;
  return /^[A-Za-z0-9_+=-]+$/.test(value) && /[0-9]/.test(value) && /[A-Za-z]/.test(value);
}

function urlSecret(url) {
  if (typeof url !== 'string') return false;
  if (/^[a-z][a-z0-9+.-]*:\/\/[^/@\s:]+:[^/@\s]+@/i.test(url)) return true; // credentials before the host
  const q = url.split('?')[1];
  if (!q) return false;
  return q.split('#')[0].split('&').some((pair) => {
    const [k, v = ''] = pair.split('=');
    return namedSecret(k, v) || literalLooksSecret(v);
  });
}

/**
 * Where an MCP server definition (either format) carries a literal credential. Returns location
 * labels only (`env API_KEY`, `args[2]`, `headers Authorization`, `url`), never a value.
 */
export function findInlineSecrets(def) {
  const out = [];
  if (!def || typeof def !== 'object') return out;
  for (const field of ['env', 'headers', 'http_headers']) {
    const obj = def[field];
    if (!obj || typeof obj !== 'object' || Array.isArray(obj)) continue;
    for (const [k, v] of Object.entries(obj)) {
      if (literalLooksSecret(v) || namedSecret(k, v) || opaqueLiteral(v)) out.push(`${field} ${k}`);
    }
  }
  const args = Array.isArray(def.args) ? def.args : [];
  args.forEach((a, i) => {
    if (typeof a !== 'string') return;
    const eq = /^--?([A-Za-z][A-Za-z0-9_-]*)=(.+)$/.exec(a);
    const prev = i > 0 && typeof args[i - 1] === 'string' ? /^--?([A-Za-z][A-Za-z0-9_-]*)$/.exec(args[i - 1]) : null;
    if (literalLooksSecret(a) || (eq && namedSecret(eq[1], eq[2])) || (prev && !a.startsWith('-') && namedSecret(prev[1], a)) || urlSecret(a)) out.push(`args[${i}]`);
  });
  if (literalLooksSecret(def.command)) out.push('command');
  if (urlSecret(def.url) || literalLooksSecret(def.url)) out.push('url');
  return out;
}

// `note` is the English sentence this file prints; `code` and `params` let a caller word it in
// another language without parsing the sentence.
const fail = (reason, note, code, params = {}) => ({ ok: false, reason, note, code, params });
const strMap = (o) => (o && typeof o === 'object' && !Array.isArray(o) ? o : {});
const wholeRef = (v) => { const m = /^\$\{([A-Za-z_][A-Za-z0-9_]*)\}$/.exec(String(v)); return m ? m[1] : null; };

/** Claude Code `mcpServers` entry -> neutral shape, or why it cannot be expressed elsewhere. */
export function claudeToNeutral(def) {
  if (!def || typeof def !== 'object') return fail('unsupported', 'the definition is not an object', 'not-object');
  const type = String(def.type || def.transport || '').toLowerCase();
  if (type === 'sse') return fail('unsupported', 'SSE transport has no equivalent in the target; use a streamable HTTP endpoint', 'sse');
  if (def.command && (type === '' || type === 'stdio')) {
    if (typeof def.command !== 'string' || HAS_REF.test(def.command)) return fail('unsupported', 'the command uses variable expansion', 'command-expansion');
    const args = Array.isArray(def.args) ? def.args.map(String) : [];
    if (args.some((a) => HAS_REF.test(a))) return fail('unsupported', 'an argument uses variable expansion the target cannot express', 'arg-expansion');
    const env = {};
    const envVars = [];
    for (const [k, v] of Object.entries(strMap(def.env))) {
      const ref = wholeRef(v);
      if (ref && ref === k) envVars.push(k);
      else if (HAS_REF.test(String(v))) return fail('unsupported', `env ${k} uses variable expansion the target cannot express`, 'env-expansion', { name: k });
      else env[k] = String(v);
    }
    return { ok: true, neutral: { transport: 'stdio', command: def.command, args, env, envVars: envVars.sort() } };
  }
  if (def.url && (type === '' || type === 'http' || type === 'streamable-http' || type === 'streamable_http')) {
    if (typeof def.url !== 'string' || HAS_REF.test(def.url)) return fail('unsupported', 'the URL uses variable expansion', 'url-expansion');
    const headers = {};
    const envHeaders = {};
    let bearerEnv = null;
    for (const [k, v] of Object.entries(strMap(def.headers))) {
      const s = String(v);
      const bearer = /^Bearer\s+\$\{([A-Za-z_][A-Za-z0-9_]*)\}$/.exec(s);
      const ref = wholeRef(s);
      if (k.toLowerCase() === 'authorization' && bearer) bearerEnv = bearer[1];
      else if (ref) envHeaders[k] = ref;
      else if (HAS_REF.test(s)) return fail('unsupported', `header ${k} uses variable expansion the target cannot express`, 'header-expansion', { name: k });
      else headers[k] = s;
    }
    return { ok: true, neutral: { transport: 'http', url: def.url, headers, envHeaders, bearerEnv } };
  }
  return fail('unsupported', 'unknown transport', 'unknown-transport');
}

/** Codex `[mcp_servers.<name>]` table -> neutral shape. */
export function codexToNeutral(def) {
  if (!def || typeof def !== 'object') return fail('unsupported', 'the definition is not a table', 'not-object');
  if (def.enabled === false) return fail('disabled', 'disabled in the primary', 'disabled');
  if (typeof def.command === 'string') {
    const envVars = [];
    for (const v of Array.isArray(def.env_vars) ? def.env_vars : []) {
      if (typeof v === 'string') envVars.push(v);
      else return fail('unsupported', 'env_vars uses a remote source', 'env-vars-remote');
    }
    const env = {};
    for (const [k, v] of Object.entries(strMap(def.env))) env[k] = String(v);
    return { ok: true, neutral: { transport: 'stdio', command: def.command, args: Array.isArray(def.args) ? def.args.map(String) : [], env, envVars: envVars.sort() } };
  }
  if (typeof def.url === 'string') {
    if (def.http_headers_helper || def.auth) return fail('unsupported', 'uses an auth helper that has no equivalent in the target', 'auth-helper');
    const headers = {};
    for (const [k, v] of Object.entries(strMap(def.http_headers))) headers[k] = String(v);
    const envHeaders = {};
    for (const [k, v] of Object.entries(strMap(def.env_http_headers))) envHeaders[k] = String(v);
    return { ok: true, neutral: { transport: 'http', url: def.url, headers, envHeaders, bearerEnv: typeof def.bearer_token_env_var === 'string' ? def.bearer_token_env_var : null } };
  }
  return fail('unsupported', 'unknown transport', 'unknown-transport');
}

export function neutralToClaude(n) {
  if (n.transport === 'stdio') {
    const out = { type: 'stdio', command: n.command };
    if (n.args.length) out.args = [...n.args];
    const env = { ...n.env };
    for (const v of n.envVars) env[v] = `\${${v}}`;
    if (Object.keys(env).length) out.env = env;
    return out;
  }
  const out = { type: 'http', url: n.url };
  const headers = { ...n.headers };
  for (const [k, v] of Object.entries(n.envHeaders)) headers[k] = `\${${v}}`;
  if (n.bearerEnv) headers.Authorization = `Bearer \${${n.bearerEnv}}`;
  if (Object.keys(headers).length) out.headers = headers;
  return out;
}

export function neutralToCodex(n) {
  if (n.transport === 'stdio') {
    const out = { command: n.command };
    if (n.args.length) out.args = [...n.args];
    if (n.envVars.length) out.env_vars = [...n.envVars];
    if (Object.keys(n.env).length) out.env = { ...n.env };
    return out;
  }
  const out = { url: n.url };
  if (n.bearerEnv) out.bearer_token_env_var = n.bearerEnv;
  if (Object.keys(n.headers).length) out.http_headers = { ...n.headers };
  if (Object.keys(n.envHeaders).length) out.env_http_headers = { ...n.envHeaders };
  return out;
}

const CODEX_NAME = /^[A-Za-z0-9_\-:@/.]+$/;

/**
 * The definition a server of the primary should have in the target, in the target's format.
 * Formats: 'claude-json' | 'codex-toml'. The same format is copied as it is; another format goes
 * through the neutral shape. A definition with an inline secret is never replicated.
 */
export function desiredServer(name, rawDef, fromFormat, toFormat) {
  const secrets = findInlineSecrets(rawDef);
  if (secrets.length) return fail('inline-secret', `carries an inline secret (${secrets.join(', ')}); move it to an environment variable in the primary first`, 'inline-secret', { where: secrets.join(', ') });
  if (toFormat === 'codex-toml' && !CODEX_NAME.test(name)) return fail('unsupported', 'the name is not valid for Codex (letters, digits and - _ : @ / . only)', 'bad-name');
  if (fromFormat === toFormat) {
    if (fromFormat === 'codex-toml' && rawDef && rawDef.enabled === false) return fail('disabled', 'disabled in the primary', 'disabled');
    return { ok: true, def: JSON.parse(JSON.stringify(rawDef)) };
  }
  const n = fromFormat === 'claude-json' ? claudeToNeutral(rawDef) : codexToNeutral(rawDef);
  if (!n.ok) return n;
  return { ok: true, def: toFormat === 'claude-json' ? neutralToClaude(n.neutral) : neutralToCodex(n.neutral) };
}

/** True when every key of `want` has the same value in `cur` (the account may add tuning keys). */
function covers(cur, want) {
  if (want === null || typeof want !== 'object' || Array.isArray(want)) return canon(cur) === canon(want);
  if (!cur || typeof cur !== 'object' || Array.isArray(cur)) return false;
  return Object.keys(want).every((k) => covers(cur[k], want[k]));
}

// ---------------------------------------------------------------------------------------------
// A tolerant TOML reader (enough for [mcp_servers.*]) and a writer for the managed tables
// ---------------------------------------------------------------------------------------------

const BARE_KEY = /^[A-Za-z0-9_-]+$/;

function skipInline(src, pos) {
  while (pos < src.length && (src[pos] === ' ' || src[pos] === '\t')) pos++;
  return pos;
}

function skipBlank(src, pos) {
  for (;;) {
    while (pos < src.length && /\s/.test(src[pos])) pos++;
    if (src[pos] !== '#') return pos;
    while (pos < src.length && src[pos] !== '\n') pos++;
  }
}

function unescapeBasic(body) {
  return body.replace(/\\(?:u([0-9A-Fa-f]{4})|U([0-9A-Fa-f]{8})|x([0-9A-Fa-f]{2})|(\r?\n)\s*|(.))/g, (all, u4, u8, x2, nl, ch) => {
    if (u4 || u8 || x2) return String.fromCodePoint(parseInt(u4 || u8 || x2, 16));
    if (nl) return '';
    return { b: '\b', t: '\t', n: '\n', f: '\f', r: '\r', e: '\u001b', '"': '"', '\\': '\\' }[ch] ?? ch;
  });
}

function parseTomlString(src, pos) {
  const q = src[pos];
  const triple = q.repeat(3);
  if (src.startsWith(triple, pos)) {
    let from = pos + 3;
    for (;;) {
      const end = src.indexOf(triple, from);
      if (end === -1) return null;
      if (q === '"') {
        let slashes = 0;
        while (src[end - 1 - slashes] === '\\') slashes++;
        if (slashes % 2 === 1) { from = end + 1; continue; }
      }
      let stop = end + 3;
      while (src[stop] === q && stop < end + 5) stop++; // one or two quotes may sit before the delimiter
      const body = src.slice(pos + 3, stop - 3).replace(/^\r?\n/, '');
      return { value: q === '"' ? unescapeBasic(body) : body, end: stop };
    }
  }
  let i = pos + 1;
  for (; i < src.length; i++) {
    const c = src[i];
    if (c === '\n') return null;
    if (q === '"' && c === '\\') { i++; continue; }
    if (c === q) break;
  }
  if (i >= src.length) return null;
  const body = src.slice(pos + 1, i);
  return { value: q === '"' ? unescapeBasic(body) : body, end: i + 1 };
}

function parseTomlKey(src, pos) {
  const parts = [];
  for (;;) {
    pos = skipInline(src, pos);
    const c = src[pos];
    if (c === '"' || c === "'") {
      const s = parseTomlString(src, pos);
      if (!s) return null;
      parts.push(s.value);
      pos = s.end;
    } else {
      const m = /^[A-Za-z0-9_-]+/.exec(src.slice(pos, pos + 256));
      if (!m) return null;
      parts.push(m[0]);
      pos += m[0].length;
    }
    pos = skipInline(src, pos);
    if (src[pos] !== '.') return { parts, end: pos };
    pos++;
  }
}

function setDeep(obj, parts, value) {
  let o = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (!o[parts[i]] || typeof o[parts[i]] !== 'object' || Array.isArray(o[parts[i]])) o[parts[i]] = {};
    o = o[parts[i]];
  }
  o[parts[parts.length - 1]] = value;
}

function getDeep(obj, parts) {
  let o = obj;
  for (const p of parts) { if (!o || typeof o !== 'object') return undefined; o = o[p]; }
  return o;
}

function parseTomlValue(src, pos) {
  pos = skipInline(src, pos);
  const c = src[pos];
  if (c === '"' || c === "'") return parseTomlString(src, pos);
  if (c === '[') {
    const arr = [];
    pos = skipBlank(src, pos + 1);
    while (pos < src.length && src[pos] !== ']') {
      const v = parseTomlValue(src, pos);
      if (!v) return null;
      arr.push(v.value);
      pos = skipBlank(src, v.end);
      if (src[pos] === ',') pos = skipBlank(src, pos + 1);
      else if (src[pos] !== ']') return null;
    }
    return pos < src.length ? { value: arr, end: pos + 1 } : null;
  }
  if (c === '{') {
    const obj = {};
    pos = skipBlank(src, pos + 1);
    while (pos < src.length && src[pos] !== '}') {
      const k = parseTomlKey(src, pos);
      if (!k) return null;
      pos = skipInline(src, k.end);
      if (src[pos] !== '=') return null;
      const v = parseTomlValue(src, pos + 1);
      if (!v) return null;
      setDeep(obj, k.parts, v.value);
      pos = skipBlank(src, v.end);
      if (src[pos] === ',') pos = skipBlank(src, pos + 1);
      else if (src[pos] !== '}') return null;
    }
    return pos < src.length ? { value: obj, end: pos + 1 } : null;
  }
  const m = /^[^,\]}#\r\n]+/.exec(src.slice(pos, pos + 512));
  if (!m) return null;
  const tok = m[0].trim();
  if (!tok) return null;
  let value;
  if (tok === 'true') value = true;
  else if (tok === 'false') value = false;
  else if (/^[+-]?\d[\d_]*(\.\d[\d_]*)?([eE][+-]?\d+)?$/.test(tok)) value = Number(tok.replace(/_/g, ''));
  else value = { $raw: tok }; // dates, hex, inf: kept verbatim
  return { value, end: pos + m[0].length };
}

function lineEnd(src, pos) {
  const nl = src.indexOf('\n', pos);
  return nl === -1 ? src.length : nl + 1;
}

/**
 * Scan a TOML text for the MCP server tables. Returns
 *   servers: { name: { def, spans: [{start, end}], inline, opaque } }
 *   markers: [{ start, end }]   the managed-block comment lines
 * `spans` are the text ranges of the server's own tables (header through its last key), so they
 * can be removed without touching anything else. `inline` servers are defined by dotted keys or
 * inline tables and are never rewritten; `opaque` ones had a line this reader could not parse.
 */
export function scanCodexServers(text) {
  const src = String(text || '');
  const servers = {};
  const markers = [];
  const get = (name) => (servers[name] ||= { def: {}, spans: [], inline: false, opaque: false });
  const inlineSet = (parts, value) => {
    const s = get(parts[0]);
    s.inline = true;
    if (parts.length > 1) setDeep(s.def, parts.slice(1), value);
    else if (value && typeof value === 'object' && !Array.isArray(value)) Object.assign(s.def, value);
  };
  let ctx = { kind: 'root' };
  let pos = 0;
  while (pos < src.length) {
    const eol = lineEnd(src, pos);
    const p = skipInline(src, pos);
    const c = src[p];
    if (c === undefined || c === '\n' || c === '\r') { pos = eol; continue; }
    if (c === '#') {
      if (src.startsWith(BLOCK_START, p) || src.startsWith(BLOCK_END, p)) markers.push({ start: pos, end: eol });
      pos = eol;
      continue;
    }
    if (c === '[') {
      const array = src[p + 1] === '[';
      const k = parseTomlKey(src, p + (array ? 2 : 1));
      ctx = { kind: 'other' };
      if (k && !array && k.parts[0] === 'mcp_servers') {
        if (k.parts.length === 1) ctx = { kind: 'parent' };
        else {
          const s = get(k.parts[1]);
          const span = { start: pos, end: eol };
          s.spans.push(span);
          const sub = k.parts.slice(2);
          if (sub.length && !getDeep(s.def, sub)) setDeep(s.def, sub, {});
          ctx = { kind: 'server', name: k.parts[1], path: sub, span };
        }
      }
      pos = eol;
      continue;
    }
    const k = parseTomlKey(src, p);
    const eq = k ? skipInline(src, k.end) : -1;
    const v = k && src[eq] === '=' ? parseTomlValue(src, eq + 1) : null;
    if (!v) {
      if (ctx.kind === 'server') servers[ctx.name].opaque = true;
      pos = eol;
      continue;
    }
    const after = lineEnd(src, v.end);
    if (ctx.kind === 'server') {
      setDeep(servers[ctx.name].def, [...ctx.path, ...k.parts], v.value);
      ctx.span.end = after;
    } else if (ctx.kind === 'parent') inlineSet(k.parts, v.value);
    else if (ctx.kind === 'root' && k.parts[0] === 'mcp_servers' && k.parts.length >= 2) inlineSet(k.parts.slice(1), v.value);
    pos = after;
  }
  return { servers, markers };
}

function tomlString(s) {
  return `"${String(s).replace(/[\\"\u0000-\u001f\u007f]/g, (ch) => {
    if (ch === '\\') return '\\\\';
    if (ch === '"') return '\\"';
    if (ch === '\n') return '\\n';
    if (ch === '\t') return '\\t';
    if (ch === '\r') return '\\r';
    return `\\u${ch.charCodeAt(0).toString(16).padStart(4, '0')}`;
  })}"`;
}

function tomlKey(k) {
  return BARE_KEY.test(k) ? k : tomlString(k);
}

function tomlValue(v) {
  if (typeof v === 'string') return tomlString(v);
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return `[${v.map(tomlValue).join(', ')}]`;
  if (v && typeof v === 'object') {
    if (typeof v.$raw === 'string') return v.$raw;
    return `{ ${Object.entries(v).map(([k, x]) => `${tomlKey(k)} = ${tomlValue(x)}`).join(', ')} }`;
  }
  return '""';
}

const isTable = (v) => !!v && typeof v === 'object' && !Array.isArray(v) && typeof v.$raw !== 'string';

/** One server as TOML lines: scalars and arrays under the header, each map as a sub-table. */
export function renderCodexServer(name, def) {
  const lines = [];
  const emit = (pathParts, obj) => {
    lines.push(`[${pathParts.map(tomlKey).join('.')}]`);
    const subs = [];
    for (const [k, v] of Object.entries(obj)) {
      if (isTable(v)) subs.push([k, v]);
      else lines.push(`${tomlKey(k)} = ${tomlValue(v)}`);
    }
    for (const [k, v] of subs) { lines.push(''); emit([...pathParts, k], v); }
  };
  emit(['mcp_servers', name], def);
  return lines;
}

/** After a removal at `offset` (a line start), drop the blank lines that would now double up. */
function closeGap(text, offset) {
  let b = offset;
  for (;;) {
    const e = lineEnd(text, b);
    if (e === b || text.slice(b, e).trim() !== '') break;
    b = e;
  }
  if (b === offset) return text;
  const before = text.slice(Math.max(0, offset - 256), offset);
  const blankBefore = offset === 0 || /(^|\n)[ \t]*\r?\n$/.test(before);
  return blankBefore ? text.slice(0, offset) + text.slice(b) : text;
}

/**
 * Rewrite the managed MCP tables of a config.toml and nothing else:
 *   remove  names whose tables are deleted (the caller has checked they are this tool's own)
 *   write   [{ name, def }]: the complete set of managed servers, written as one block at the end
 * Tables named in either list are removed wherever they sit, the old block markers are removed,
 * and the block is appended between `# novarc-harness-doctor:start` and `:end`. Every other byte
 * of the file is kept. Throws when a named server is defined in a form that cannot be cut out.
 */
export function rewriteCodexServers(text, { remove = [], write = [] }) {
  const src = String(text || '');
  const eol = src.includes('\r\n') ? '\r\n' : '\n';
  const scan = scanCodexServers(src);
  const cuts = [...scan.markers];
  for (const name of new Set([...remove, ...write.map((w) => w.name)])) {
    const s = scan.servers[name];
    if (!s) continue;
    if (s.inline || s.opaque) throw new Error(`server "${name}" is defined in a form this tool does not rewrite`);
    cuts.push(...s.spans);
  }
  let out = src;
  for (const c of cuts.sort((x, y) => y.start - x.start)) out = closeGap(out.slice(0, c.start) + out.slice(c.end), c.start);
  out = out.replace(/\s+$/, '');
  if (!write.length) return out ? out + eol : '';
  const block = [`${BLOCK_START} (managed: edit the primary account, then run the sync check)`];
  write.forEach((w, i) => { if (i) block.push(''); block.push(...renderCodexServer(w.name, w.def)); });
  block.push(BLOCK_END);
  return (out ? out + eol + eol : '') + block.join(eol) + eol;
}

/**
 * Read the MCP servers of one account file ('claude-json': the `mcpServers` key of the account
 * state file, and only that key; 'codex-toml': the `[mcp_servers.*]` tables of config.toml).
 */
export function readServers(file, format) {
  if (!lstatSafe(file)) return { ok: true, exists: false, text: '', servers: {} };
  const text = readText(file, 64 * 1024 * 1024);
  if (text === null) return { ok: false, exists: true, servers: {} };
  if (format === 'codex-toml') return { ok: true, exists: true, text, servers: scanCodexServers(text).servers };
  const j = parseJson(text);
  if (!j.ok || !j.value || typeof j.value !== 'object' || Array.isArray(j.value)) return { ok: false, exists: true, servers: {} };
  const map = j.value.mcpServers && typeof j.value.mcpServers === 'object' && !Array.isArray(j.value.mcpServers) ? j.value.mcpServers : {};
  const servers = {};
  for (const [name, def] of Object.entries(map)) servers[name] = { def, spans: [], inline: false, opaque: false };
  return { ok: true, exists: true, text, servers };
}

/**
 * Compare the primary's MCP servers with one account's, server by server.
 *   source, target  { name: { def } } as readServers returns them
 *   managed         { name: contentHash } from the manifest: what this tool wrote last time
 *   exceptions      element names the user keeps as account exceptions
 * Each item is { name, status, want?, note? } with status
 *   ok           in step and managed            ok-foreign    in step, defined by the account
 *   missing      not in the account             stale         managed, untouched, primary changed
 *   edited       managed, changed by hand       differs       the account's own, different
 *   gone         managed, no longer wanted      gone-edited   same, but changed by hand
 *   account-only only in the account            excepted      kept as an exception
 *   blocked      cannot be replicated (inline secret, unsupported transport)
 * `want` is the definition to write, in the target's format. Only `missing`, `stale` and `gone`
 * may be changed without asking.
 */
export function reconcileServers({ source, target, sourceFormat, targetFormat, managed = {}, exceptions = [] }) {
  const except = new Set(exceptions);
  const items = [];
  const names = new Set([...Object.keys(source), ...Object.keys(target), ...Object.keys(managed)]);
  for (const name of [...names].sort()) {
    const el = MCP_PREFIX + name;
    const cur = target[name];
    const mine = Object.prototype.hasOwnProperty.call(managed, name);
    const untouched = !!cur && mine && !cur.inline && !cur.opaque && sha256(canon(cur.def)) === managed[name];
    if (!source[name]) {
      if (!cur) { if (mine) items.push({ name, status: 'gone', absent: true }); continue; }
      if (!mine) items.push({ name, status: except.has(el) ? 'excepted' : 'account-only' });
      else items.push({ name, status: untouched ? 'gone' : 'gone-edited', note: 'no longer in the primary' });
      continue;
    }
    if (except.has(el)) { items.push({ name, status: 'excepted', present: !!cur }); continue; }
    const d = desiredServer(name, source[name].def, sourceFormat, targetFormat);
    if (!d.ok) {
      if (cur && untouched) items.push({ name, status: 'gone', note: d.note, code: d.code, params: d.params });
      else items.push({ name, status: 'blocked', reason: d.reason, note: d.note, code: d.code, params: d.params, present: !!cur });
      continue;
    }
    if (!cur) { items.push({ name, status: 'missing', want: d.def }); continue; }
    if (covers(cur.def, d.def)) { items.push({ name, status: mine ? 'ok' : 'ok-foreign', want: d.def, exact: canon(cur.def) === canon(d.def) }); continue; }
    items.push({ name, status: untouched ? 'stale' : mine ? 'edited' : 'differs', want: d.def });
  }
  return items;
}

// ---------------------------------------------------------------------------------------------
// Manifest
// ---------------------------------------------------------------------------------------------

export function readManifest(file = manifestFile()) {
  const text = readText(file);
  if (text === null) return null;
  const j = parseJson(text);
  if (!j.ok || !j.value || j.value.version !== MANIFEST_VERSION || !Array.isArray(j.value.accounts)) return null;
  for (const a of j.value.accounts) {
    if (!Array.isArray(a.elements)) a.elements = [];
    if (!Array.isArray(a.exceptions)) a.exceptions = [];
  }
  return j.value;
}

/** The bytes of a manifest file, stamped with the time of writing. */
export function manifestText(manifest) {
  manifest.updatedAt = new Date().toISOString();
  return JSON.stringify(manifest, null, 2) + '\n';
}

export function writeManifest(manifest, file = manifestFile()) {
  writeAtomic(file, manifestText(manifest));
}

// ---------------------------------------------------------------------------------------------
// The check
// ---------------------------------------------------------------------------------------------

function checkLink(el, repair, home) {
  const st = linkStatus(el.path, el.target);
  if (st.state === 'ok') {
    if (repair && !el.place) el.place = placeOf(el.path); // a manifest from before places were recorded
    return { state: 'ok' };
  }
  // Something is to be made, replaced or removed at that path: only in the folder the link was
  // made in. A copy "nobody edited" behind a redirected folder is somebody else's file.
  if (el.place && !placeHolds(el.place, el.path)) return { state: 'drift', note: 'its folder was moved, replaced or redirected; not repaired', both: true };
  const targetExists = !!statSafe(el.target);
  if (st.state === 'missing') {
    if (!targetExists) return { state: 'broken', note: 'the link is gone and so is its source in the primary', gone: 'both' };
    if (!repair) return { state: 'broken', note: 'the link is gone' };
    el.kind = createLink(el.target, el.path, isDir(el.target));
    return { state: 'broken', note: 'the link was gone', repaired: true };
  }
  if (st.state === 'dangling') return { state: 'broken', note: 'its source is missing in the primary', gone: 'link' };
  if (st.state === 'other-link') return { state: 'drift', note: 'the link points somewhere else', both: true };
  if (st.kind === 'dir' || el.dir) return { state: 'drift', note: 'a real folder or file replaced the link', both: true };
  if (!targetExists) return { state: 'broken', note: 'its source is missing in the primary', gone: 'copy' };
  // A real file sits where the link was. It is safe to link again only when nobody edited it:
  // it is byte-identical to the primary, or to the content last seen through the link.
  const here = hashFile(el.path);
  const identical = here !== null && here === hashFile(el.target);
  const unedited = here !== null && !!el.contentHash && here === el.contentHash;
  if (!identical && !unedited) return { state: 'drift', note: 'edited by hand; not overwritten', both: true };
  if (!repair) return { state: 'broken', note: identical ? 'the link became a separate identical copy' : 'the link broke and the primary changed since' };
  try { el.kind = relinkFile(el.target, el.path, home, { hash: here, place: el.place }); } catch (e) {
    // Judged a moment ago to be a copy nobody edited; somebody did, before it could be replaced.
    if (e && e.code === 'ECHANGED') return { state: 'drift', note: 'edited while it was being linked again; not overwritten', both: true };
    throw e;
  }
  return { state: 'broken', note: 'the link had become a separate copy', repaired: true };
}

/** What a generated element should contain now, or null when its source is gone. */
function regenerate(el, home) {
  const g = el.generator || {};
  if (g.type === 'copy') return readBuf(el.target);
  const r = generateInstructions({ source: el.target, provider: g.provider, sourceDisplay: g.sourceDisplay || displayPath(el.target, home), inlineImports: g.inlineImports !== false, home });
  return r ? Buffer.from(r.text, 'utf8') : null;
}

function checkGenerated(el, repair, home, acct) {
  const want = regenerate(el, home);
  if (want === null) return { state: 'broken', note: 'its source is missing in the primary', gone: lstatSafe(el.path) ? 'copy' : 'both' };
  const wantHash = sha256(want);
  const there = !!lstatSafe(el.path);
  const here = there ? hashFile(el.path) : null;
  if (here === wantHash) {
    if (repair && el.contentHash !== wantHash) { el.contentHash = wantHash; el.sourceHash = wantHash; }
    // A manifest from before destinations were recorded: this one is adopted only while it is
    // provably the generated file (a plain single-name file, a link-free path, the generated bytes).
    if (repair && !el.identity && !destinationProblem(null, el.path, acct.pathAbs)) el.identity = destIdentity(el.path);
    return { state: 'ok' };
  }
  if (here !== null && here !== el.contentHash) return { state: 'drift', note: 'edited by hand; not overwritten', both: true };
  const state = here === null ? 'broken' : 'drift';
  const note = there ? 'the primary changed' : 'the generated file was gone';
  // Is the destination still the one that was generated? Asked before anything is written, and
  // without --repair too, so the report never promises a repair that would be refused.
  const problem = destinationProblem(el.identity, el.path, acct.pathAbs);
  if (problem) return { state, note: `${problem}; not rewritten`, both: true };
  if (there && here === null) return { state, note: 'it cannot be read; not rewritten' };
  if (!repair) return { state, note };
  try { writeKeepingLinks(el.path, want, { home, expect: here }); } catch (e) {
    return { state, note: `${note}; could not be rewritten (${scrub(String(e && (e.code || e.message)), home)}), so it is as it was` };
  }
  el.contentHash = wantHash;
  el.sourceHash = wantHash;
  el.identity = destIdentity(el.path);
  return { state, note, repaired: true };
}

function checkServers(acct, results, repair, home) {
  const m = acct.mcp;
  if (!m) return false;
  const els = acct.elements.filter((e) => e.kind === 'managed-block');
  const report = (name, r) => results.push({ account: acct.id, name: MCP_PREFIX + name, path: m.path, target: m.source, ...r });
  const src = readServers(m.source, m.sourceFormat);
  const tgt = readServers(m.path, m.format);
  if (!src.ok || !src.exists || !tgt.ok) {
    const note = !tgt.ok ? 'the account file cannot be read' : 'the primary\'s server list cannot be read';
    for (const e of els) report(e.name.slice(MCP_PREFIX.length), { state: 'broken', note });
    return false;
  }
  const managed = {};
  for (const e of els) managed[e.name.slice(MCP_PREFIX.length)] = e.contentHash;
  const items = reconcileServers({ source: src.servers, target: tgt.servers, sourceFormat: m.sourceFormat, targetFormat: m.format, managed, exceptions: acct.exceptions });
  // The state file of a running app is never written by an unattended check: what is behind
  // there is reported as `manual` (plan and apply with the app closed).
  // The same holds for a config file that became a link, gained a hardlink or sits behind a
  // redirected folder: unattended, only a plain single-name file at its recorded place is written.
  const writable = m.format === 'codex-toml';
  let problem;
  const blocked = () => { if (problem === undefined) problem = writable ? destinationProblem(m.identity, m.path, acct.pathAbs) : null; return problem; };
  const canWrite = () => repair && writable && !blocked();
  const behind = (name, note) => {
    const why = writable ? blocked() : null;
    report(name, { state: 'drift', note: why ? `${note}; the account file is not written here: ${why}` : note, ...(writable && !why ? {} : { manual: true }) });
  };
  const write = [];
  const remove = [];
  const pending = [];
  let dirty = false;
  const drop = (name) => { acct.elements = acct.elements.filter((e) => e.name !== MCP_PREFIX + name); dirty = true; };
  for (const it of items) {
    const mine = Object.prototype.hasOwnProperty.call(managed, it.name);
    if (it.status === 'ok') {
      report(it.name, { state: 'ok' });
      if (it.exact) write.push({ name: it.name, def: it.want });
    } else if (it.status === 'missing' || it.status === 'stale') {
      const note = it.status === 'stale' ? 'the primary changed' : mine ? 'the definition was gone' : 'new in the primary';
      if (canWrite()) { write.push({ name: it.name, def: it.want }); pending.push({ name: it.name, note }); } else behind(it.name, note);
    } else if (it.status === 'gone') {
      const note = it.note || 'no longer in the primary';
      if (it.absent) { if (repair) drop(it.name); } else if (canWrite()) { remove.push(it.name); pending.push({ name: it.name, note, removed: true }); } else behind(it.name, note);
    } else if (it.status === 'edited' || it.status === 'gone-edited') report(it.name, { state: 'drift', note: 'edited by hand; not overwritten', both: true });
    else if (it.status === 'blocked' && mine) report(it.name, { state: 'drift', note: it.note });
  }
  if (!pending.length) {
    // A manifest from before destinations were recorded: adopt this one while it is provably safe.
    if (repair && writable && els.length && !m.identity && tgt.exists && !blocked()) { m.identity = destIdentity(m.path, { ids: false }); dirty = true; }
    return dirty;
  }
  try {
    const next = rewriteCodexServers(tgt.text, { remove, write });
    // `expect`: the bytes `next` was worked out from. A file the app saved in between is not written.
    writeKeepingLinks(m.path, next, { home, expect: tgt.exists ? sha256(Buffer.from(tgt.text, 'utf8')) : null });
    m.identity = destIdentity(m.path, { ids: false });
    const after = scanCodexServers(next).servers;
    for (const p of pending) {
      drop(p.name);
      if (!p.removed) acct.elements.push({ name: MCP_PREFIX + p.name, kind: 'managed-block', path: m.path, target: m.source, sourceHash: sha256(canon(src.servers[p.name].def)), contentHash: sha256(canon(after[p.name].def)) });
      report(p.name, { state: 'drift', note: p.note, repaired: true });
    }
    return true;
  } catch (e) {
    // A failed write changes nothing: the account file holds what it held.
    for (const p of pending) report(p.name, { state: 'drift', note: `could not be repaired (${scrub(String(e && e.message), home)})` });
    return dirty;
  }
}

/** What the primary gained since the last apply: new imports (linked) and new skills. */
function checkAdditions(acct, results, repair, home) {
  let dirty = false;
  const known = new Set(acct.elements.map((e) => e.name));
  const except = new Set(acct.exceptions);
  const candidates = [];
  if (acct.imports && acct.imports.source && acct.imports.root) {
    const covered = new Set((acct.imports.coveredDirs || []).map((d) => d.toLowerCase()));
    for (const abs of collectImports(acct.imports.source, { home })) {
      if (!isInside(abs, acct.imports.root)) continue;
      const rel = path.relative(acct.imports.root, abs).replace(/\\/g, '/');
      const top = rel.split('/')[0];
      if (isNeverTop(top) || covered.has(top.toLowerCase())) continue;
      candidates.push({ name: rel, target: abs, path: path.join(acct.pathAbs, rel), dir: false });
    }
  }
  if (acct.skills && acct.skills.source && acct.skills.target && isDir(acct.skills.target)) {
    for (const ent of readdirSafe(acct.skills.source)) {
      if (ent.name.startsWith('.')) continue;
      const abs = path.join(acct.skills.source, ent.name);
      if (!isFile(path.join(abs, 'SKILL.md'))) continue;
      candidates.push({ name: SKILL_PREFIX + ent.name, target: abs, path: path.join(acct.skills.target, ent.name), dir: true });
    }
  }
  const accountReal = realpathSafe(acct.pathAbs);
  for (const c of candidates) {
    if (known.has(c.name) || except.has(c.name)) continue;
    // Nothing new is linked through a folder of the account that leads out of it: said, with
    // both paths, until the user decides (put the folder back, or plan and apply again).
    const into = realParent(c.path);
    if (!accountReal || !into || !isInside(into, accountReal)) {
      results.push({ account: acct.id, name: c.name, path: c.path, target: c.target, state: 'drift', note: 'new in the primary, but its folder now leads outside the account folder; not linked', both: true });
      continue;
    }
    const st = linkStatus(c.path, c.target);
    const element = (kind) => linkRecord(c.name, kind, c.path, c.target, c.dir);
    if (st.state === 'ok') {
      if (repair) { acct.elements.push(element(st.kind === 'hardlink' ? 'hardlink' : 'symlink')); dirty = true; }
      continue;
    }
    if (st.state !== 'missing') continue; // something else lives there: the plan decides, not the check
    const where = { account: acct.id, name: c.name, path: c.path, target: c.target };
    if (!repair) { results.push({ ...where, state: 'drift', note: 'new in the primary, not linked yet' }); continue; }
    try {
      acct.elements.push(element(linkOrCopy(c.target, c.path, c.dir, home)));
      results.push({ ...where, state: 'drift', note: 'new in the primary', repaired: true });
      dirty = true;
    } catch (e) {
      results.push({ ...where, state: 'broken', note: `could not be linked (${scrub(String(e && e.code))})` });
    }
  }
  return dirty;
}

/**
 * Verify every managed element. Returns
 *   { status: 'none'|'ok'|'drift'|'broken', primary, accounts: [{ id, provider, mode, status,
 *     elements: [{ name, state, note?, repaired?, decide?, path?, source? }] }],
 *     counts: { ok, drift, broken, repaired }, recovered?: [...] }
 * `status` is what is still wrong after any repair. `decide` marks what somebody changed by hand
 * (never overwritten). `recovered` is there only when an earlier run died in the middle of a
 * write: what recoverWrites found, and with `repair` did about it, before anything was checked.
 * Paths are display paths. Never throws.
 */
export function runCheck({ repair = false, file, home = homeDir() } = {}) {
  const mf = file || manifestFile(home);
  const counts = { ok: 0, drift: 0, broken: 0, repaired: 0 };
  const interrupted = recoverWrites({ home, repair });
  const recovered = interrupted.length ? { recovered: interrupted } : {};
  const manifestWas = hashFile(mf);
  const manifest = readManifest(mf);
  if (!manifest) return { status: 'none', primary: null, accounts: [], counts, ...recovered };
  const results = [];
  let dirty = false;
  // Deletions in the primary are mirrored only while the primary itself is there: a primary on
  // a volume that is not mounted must not look like "the user deleted everything".
  const primaryThere = !manifest.primaryPathAbs || isDir(manifest.primaryPathAbs);
  for (const acct of manifest.accounts) {
    // An account whose folder is gone is said once (`orphan` remembers it); nothing is
    // re-created inside it. The next plan and apply drop it from the manifest.
    if (!isDir(acct.pathAbs)) {
      if (!acct.orphan) results.push({ account: acct.id, name: '(account)', path: acct.pathAbs, state: 'broken', note: 'the account folder is gone' });
      if (repair && !acct.orphan) { acct.orphan = true; dirty = true; }
      continue;
    }
    if (acct.orphan) { delete acct.orphan; dirty = true; }
    const recorded = !!acct.dir;
    const moved = accountMoved(acct, repair);
    if (!recorded && acct.dir) dirty = true;
    if (moved) { results.push({ account: acct.id, name: '(account)', path: acct.pathAbs, state: 'drift', note: moved, both: true }); continue; }
    const dropped = new Set();
    for (const el of acct.elements) {
      if (el.kind === 'managed-block') continue;
      if (el.orphan) {
        if (!statSafe(el.target)) continue; // already said once: its source left the primary
        delete el.orphan;
        dirty = true;
      }
      let r;
      const mark = () => `${el.kind}|${el.contentHash || ''}|${el.identity ? JSON.stringify(el.identity) : ''}|${el.place ? JSON.stringify(el.place) : ''}`;
      const before = mark();
      try {
        r = el.kind === 'generated' ? checkGenerated(el, repair, home, acct) : checkLink(el, repair, home);
        if (repair && el.kind !== 'generated' && !el.dir && (r.state === 'ok' || r.repaired)) {
          const h = hashFile(el.target); // the content last seen through the link
          if (h) el.contentHash = h;
        }
        if (repair && r.gone && primaryThere) {
          // The source left the primary. A link that now points nowhere is removed; a file with
          // content stays (it may be all that is left) and is mentioned this once.
          dirty = true;
          if (r.gone === 'both') { dropped.add(el); continue; }
          if (r.gone === 'link') { removeLink(el.path); dropped.add(el); r = { state: 'broken', note: 'removed from the primary', repaired: true }; } else { el.orphan = true; r = { state: 'broken', note: 'its source was removed from the primary; this copy is left as it is' }; }
        }
      } catch (e) {
        r = { state: 'broken', note: `could not be checked (${scrub(String(e && (e.code || e.message)))})` };
      }
      if (before !== mark()) dirty = true;
      results.push({ account: acct.id, name: el.name, path: el.path, target: el.target, ...r });
    }
    if (dropped.size) acct.elements = acct.elements.filter((e) => !dropped.has(e));
    try { if (checkServers(acct, results, repair, home)) dirty = true; } catch (e) {
      results.push({ account: acct.id, name: 'mcp servers', state: 'broken', note: `could not be checked (${scrub(String(e && (e.code || e.message)))})` });
    }
    try { if (checkAdditions(acct, results, repair, home)) dirty = true; } catch { /* additions are best effort */ }
  }
  if (repair && dirty && hashFile(mf) === manifestWas) {
    // Only while the manifest is still the one that was read: another run (an apply) may have
    // written it in the meantime, and what this run noted is noted again by the next one.
    try { writeManifest(manifest, mf); } catch { /* the next run records it */ }
  }
  const accounts = manifest.accounts.map((acct) => {
    const elements = results.filter((r) => r.account === acct.id).map((r) => {
      const out = { name: r.name, state: r.repaired ? 'ok' : r.state };
      if (r.note) out.note = r.note;
      if (r.repaired) out.repaired = true;
      if (r.both) out.decide = true; // somebody changed it by hand: the user chooses which side wins
      if (r.manual && !r.repaired) out.manual = true; // only `accounts.mjs apply` may write that file
      if (r.state !== 'ok' && r.path) out.path = displayPath(r.path, home);
      if (r.state !== 'ok' && r.target) out.source = displayPath(r.target, home);
      counts[r.repaired ? 'repaired' : r.state]++;
      return out;
    });
    const status = elements.some((e) => e.state === 'broken') ? 'broken' : elements.some((e) => e.state === 'drift') ? 'drift' : 'ok';
    return { id: acct.id, provider: acct.provider, mode: acct.mode, status, elements };
  });
  return { status: counts.broken ? 'broken' : counts.drift ? 'drift' : 'ok', primary: manifest.primary, accounts, counts, ...recovered };
}

/** The one line a session-start hook prints, or an empty string when there is nothing to say. */
export function summaryLine(report) {
  const repaired = [];
  const decide = []; // changed by hand: shown first, with both paths
  const wrong = [];
  for (const a of report.accounts) {
    let manual = 0;
    for (const e of a.elements) {
      if (e.repaired) repaired.push(`${a.id} ${e.name}`);
      else if (e.state === 'ok') continue;
      else if (e.manual) manual++;
      else if (e.decide) decide.push(`${a.id} ${e.name}: ${e.note}${e.path && e.source ? ` (${e.path} vs ${e.source})` : ''}`);
      else wrong.push(`${a.id} ${e.name}: ${e.note || e.state}`);
    }
    if (manual) wrong.push(`${a.id}: ${manual} MCP server${manual === 1 ? '' : 's'} behind the primary (run accounts.mjs plan, then apply with the app closed)`);
  }
  // What an interrupted run left: said first when it was dealt with, as attention when it waits.
  const recovered = [];
  const waiting = [];
  for (const r of report.recovered || []) (r.outcome === 'pending' || r.outcome === 'waiting' || r.outcome === 'conflict' || r.foreign ? waiting : recovered).push(recoveryText(r));
  const attention = [...waiting, ...decide, ...wrong];
  if (!repaired.length && !attention.length && !recovered.length) return '';
  const cut = (list, n) => (list.length > n ? `${list.slice(0, n).join('; ')}; +${list.length - n} more` : list.join('; '));
  const parts = [];
  if (recovered.length) parts.push(`recovered ${recovered.length} (${cut(recovered, 3)})`);
  if (repaired.length) parts.push(`repaired ${repaired.length} (${cut(repaired, 4)})`);
  if (attention.length) parts.push(`needs attention ${attention.length} (${cut(attention, 3)})`);
  return `${TOOL} account sync: ${parts.join('; ')}.`;
}

function isMainModule() {
  try {
    const self = fs.realpathSync(fileURLToPath(import.meta.url));
    const argv1 = process.argv[1] ? fs.realpathSync(process.argv[1]) : '';
    return IS_WIN ? self.toLowerCase() === argv1.toLowerCase() : self === argv1;
  } catch { return false; }
}

if (isMainModule()) {
  // Whatever happens, a session must never be blocked by this script: it always exits 0.
  try {
    const flags = new Set(process.argv.slice(2));
    // A copy installed next to its manifest uses that manifest, and the home it sits in,
    // whatever the environment of the session says.
    const here = path.dirname(fileURLToPath(import.meta.url));
    const beside = path.join(here, 'manifest.json');
    const installed = lstatSafe(beside) && pathKey(syncDir(path.resolve(here, '..', '..', '..'))) === pathKey(here);
    const report = runCheck({ repair: flags.has('--repair'), ...(installed ? { file: beside, home: path.resolve(here, '..', '..', '..') } : {}) });
    if (flags.has('--json')) process.stdout.write(JSON.stringify(report, null, 2) + '\n');
    else {
      const line = summaryLine(report);
      if (line) process.stdout.write(line + '\n');
    }
  } catch { /* silent by contract */ }
  process.exitCode = 0;
}
